const SUBJECTS_DATA = {"dbms": {"code": "BCA-501", "paperCode": "18021", "title": "Introduction to DBMS", "desc": "Database models, Relational Algebra, SQL, Normalization (1NF-BCNF), Transactions, 2PL, & Three-Schema Architecture.", "icon": "fa-database", "color": "blue", "pdfBank": "pdfs/BCA501_DBMS.pdf", "years": [{"year": "2025", "pdf": "pdfs/dbms_2025.pdf"}, {"year": "2024", "pdf": "pdfs/dbms_2024.pdf"}, {"year": "2023", "pdf": "pdfs/dbms_2023.pdf"}, {"year": "2021", "pdf": "pdfs/dbms_2021.pdf"}, {"year": "2020", "pdf": "pdfs/dbms_2020.pdf"}, {"year": "2019", "pdf": "pdfs/dbms_2019.pdf"}, {"year": "2018", "pdf": "pdfs/dbms_2018.pdf"}, {"year": "2017", "pdf": "pdfs/dbms_2017.pdf"}, {"year": "2016", "pdf": "pdfs/dbms_2016.pdf"}, {"year": "2015", "pdf": "pdfs/dbms_2015.pdf"}, {"year": "2014", "pdf": "pdfs/dbms_2014.pdf"}, {"year": "2013", "pdf": "pdfs/dbms_2013.pdf"}], "contentHtml": "<!-- ==================== SECTION A ==================== -->\n<div class=\"sec-title\">Section – A (Very Short Answer Questions &bull; 3 Marks Each &bull; All 5 Compulsory)</div>\n\n<!-- Q1 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q1. Define Database Management System (DBMS) and its fundamental purpose. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>A <b>Database Management System (DBMS)</b> is a specialized software package designed to define, construct, manipulate, and share structured databases among various users and applications.</p>\n    <div class=\"info-box\">\n        <p><b>Four Fundamental Purposes of DBMS:</b></p>\n        <ol>\n            <li><b>Controlled Redundancy:</b> Integrates multiple logical files to eliminate duplicate data storage.</li>\n            <li><b>Data Consistency & Integrity:</b> Enforces business constraints and ACID properties across operations.</li>\n            <li><b>Concurrent Multi-User Access:</b> Allows hundreds of simultaneous users to access data without conflicts.</li>\n            <li><b>Data Security & Recovery:</b> Provides role-based access control, transaction logs, and disaster recovery.</li>\n        </ol>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q2 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q2. Distinguish between Simple and Composite Attributes with examples. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 20%;\">Attribute Type</th>\n            <th style=\"width: 45%;\">Definition & Characteristic</th>\n            <th style=\"width: 35%;\">Real-World Examples</th>\n        </tr>\n        <tr>\n            <td><b>Simple Attribute (Atomic)</b></td>\n            <td>Cannot be further divided into smaller independent sub-components. Holds a single atomic value.</td>\n            <td><code>Roll_No</code>, <code>Age</code>, <code>Gender</code>, <code>Salary</code></td>\n        </tr>\n        <tr>\n            <td><b>Composite Attribute</b></td>\n            <td>Can be divided into smaller sub-attributes, each having independent semantic meaning.</td>\n            <td><code>Name</code> &rarr; (First, Middle, Last)<br><code>Address</code> &rarr; (Street, City, State, PIN)</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q3 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q3. Explain Referential Integrity Constraint. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Referential Integrity</b> is a relational constraint between two relations (tables) maintained through a <b>Foreign Key</b>. It dictates that:</p>\n    <div class=\"info-box\">\n        <p>A value in the Foreign Key column of the referencing table <b>MUST</b> either match an existing Primary Key value in the referenced table, or otherwise be <code>NULL</code>.</p>\n    </div>\n    <ul>\n        <li><b>Prevents Orphan Records:</b> Prevents child records from pointing to non-existent parent rows.</li>\n        <li><b>Cascading Actions:</b>\n            <ul>\n                <li><code>ON DELETE CASCADE</code>: Deleting a parent row automatically deletes all matching child rows.</li>\n                <li><code>ON DELETE SET NULL</code>: Deleting a parent row resets foreign key fields in child rows to <code>NULL</code>.</li>\n            </ul>\n        </li>\n    </ul>\n</div>\n\n<hr>\n\n<!-- Q4 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q4. Differentiate between DDL and DML commands with syntax. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Feature</th>\n            <th style=\"width: 38%;\">DDL (Data Definition Language)</th>\n            <th style=\"width: 37%;\">DML (Data Manipulation Language)</th>\n        </tr>\n        <tr>\n            <td><b>Primary Objective</b></td>\n            <td>Defines, alters, and drops database schema structures and tables.</td>\n            <td>Manages, inserts, updates, and retrieves data tuples within existing tables.</td>\n        </tr>\n        <tr>\n            <td><b>Transaction Behavior</b></td>\n            <td><b>Auto-committed</b> immediately; changes cannot be rolled back via TCL.</td>\n            <td><b>Not auto-committed</b> by default; can be committed or rolled back using <code>ROLLBACK</code>.</td>\n        </tr>\n        <tr>\n            <td><b>Key SQL Commands & Syntax</b></td>\n            <td>\n                <code>CREATE TABLE Student(Id INT);</code><br>\n                <code>ALTER TABLE Student ADD Age INT;</code><br>\n                <code>DROP TABLE Student;</code><br>\n                <code>TRUNCATE TABLE Student;</code>\n            </td>\n            <td>\n                <code>INSERT INTO Student VALUES(1, 20);</code><br>\n                <code>UPDATE Student SET Age=21 WHERE Id=1;</code><br>\n                <code>DELETE FROM Student WHERE Id=1;</code><br>\n                <code>SELECT * FROM Student;</code>\n            </td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q5 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q5. Explain Functional Dependency (FD) and Multivalued Dependency (MVD). <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <div class=\"info-box\">\n        <p class=\"step-label\">1. Functional Dependency (X &rarr; Y):</p>\n        <p>A constraint between two sets of attributes X and Y in relation R. It states that for any two tuples t<sub>1</sub> and t<sub>2</sub>, if <code>t<sub>1</sub>[X] = t<sub>2</sub>[X]</code>, then <code>t<sub>1</sub>[Y] = t<sub>2</sub>[Y]</code> must also hold. Attribute set X uniquely determines attribute set Y.</p>\n        <p><i>Example: <code>Roll_No &rarr; Student_Name, Branch</code></i></p>\n    </div>\n    <div class=\"info-box\">\n        <p class=\"step-label\">2. Multivalued Dependency (X &twoheadrightarrow; Y):</p>\n        <p>Occurs when presence of one or more rows in a table implies the presence of other rows. For a tuple (x, y, z), attribute set Y depends only on X and is completely independent of attribute set Z. MVD leads to <b>4NF decomposition</b>.</p>\n        <p><i>Example: In table (Course, Teacher, Book), if Course determines multiple Teachers and multiple Books independently: <code>Course &twoheadrightarrow; Teacher</code> and <code>Course &twoheadrightarrow; Book</code>.</i></p>\n    </div>\n</div>\n\n<!-- ==================== SECTION B ==================== -->\n<div class=\"sec-title\">Section – B (Short Answer Questions &bull; 7.5 Marks Each &bull; Attempt Any Two)</div>\n\n<!-- Q6 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q6. Discuss Anomalies associated with Relational Database (Insertion, Deletion, Update). <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>When relational schemas are unnormalized, redundant information causes three major operational anomalies:</p>\n    <div class=\"info-box\">\n        <p><b>Consider Unnormalized Relation:</b> <code>Emp_Dept(EmpId, EmpName, DeptId, DeptName, DeptHOD)</code></p>\n    </div>\n    <ol>\n        <li>\n            <b>Insertion Anomaly:</b>\n            <p>Occurs when certain facts cannot be recorded without prematurely adding unrelated attributes. For example, a new department (e.g., DeptId = 'D99', DeptName = 'AI Research') cannot be inserted until at least one employee is hired, because <code>EmpId</code> is the primary key and cannot accept <code>NULL</code>.</p>\n        </li>\n        <li>\n            <b>Deletion Anomaly:</b>\n            <p>Occurs when deleting one piece of data inadvertently destroys critical unrelated information. For example, if employee 'E101' is the sole member of department 'D05', deleting employee 'E101' simultaneously deletes all records of department 'D05' (its name, budget, HOD) from the database.</p>\n        </li>\n        <li>\n            <b>Update (Modification) Anomaly:</b>\n            <p>Occurs when data redundancy causes duplicate copies across multiple tuples. If department 'D01' has 500 employees, changing the department name requires updating all 500 rows. Missing even one row results in conflicting, inconsistent database states.</p>\n        </li>\n    </ol>\n    <p><b>Solution:</b> Normalization decomposes such relations into separate tables (e.g., <code>Employee</code> and <code>Department</code>) linked by foreign keys.</p>\n</div>\n\n<hr>\n\n<!-- Q7 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q7. Explain Super Key, Candidate Key, and Primary Key with suitable examples. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Consider relation: <code>Student(RollNo, RegNo, Email, Name, Age, Phone)</code></p>\n    <div class=\"info-box\">\n        <p><b>Hierarchical Relationship:</b> Super Key &supd; Candidate Key &supd; Primary Key</p>\n    </div>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 22%;\">Key Category</th>\n            <th style=\"width: 48%;\">Formal Definition & Properties</th>\n            <th style=\"width: 30%;\">Examples from Student</th>\n        </tr>\n        <tr>\n            <td><b>Super Key</b></td>\n            <td>Any set of one or more attributes that uniquely identifies each tuple in a relation. May contain redundant attributes.</td>\n            <td>\n                <code>{RollNo}</code><br>\n                <code>{RegNo}</code><br>\n                <code>{Email}</code><br>\n                <code>{RollNo, Name}</code><br>\n                <code>{RegNo, Age, Phone}</code>\n            </td>\n        </tr>\n        <tr>\n            <td><b>Candidate Key</b></td>\n            <td>A <b>minimal</b> super key. Contains no extraneous attributes; removing any single attribute destroys unique identification.</td>\n            <td>\n                <code>{RollNo}</code><br>\n                <code>{RegNo}</code><br>\n                <code>{Email}</code>\n            </td>\n        </tr>\n        <tr>\n            <td><b>Primary Key</b></td>\n            <td>The single candidate key chosen by the database designer as the principal unique identifier. <b>Cannot be NULL</b> and must be unique.</td>\n            <td><code>{RollNo}</code> (Chosen as primary key)</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q8 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q8. What is Normalization? Explain Second Normal Form (2NF) and Third Normal Form (3NF). <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Normalization</b> is a systematic technique for structuring relational tables to eliminate data redundancy, prevent insertion/deletion/update anomalies, and preserve data integrity.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">1. Second Normal Form (2NF):</p>\n        <ul>\n            <li><b>Condition 1:</b> Relation must already satisfy First Normal Form (1NF) — all attributes atomic.</li>\n            <li><b>Condition 2:</b> <b>No Partial Dependency:</b> Every non-prime attribute must depend on the <i>entire</i> candidate key, not on any proper subset of a composite candidate key.</li>\n        </ul>\n        <p><i>Example: In <code>StudentCourse(StudentID, CourseID, Grade, CourseName)</code> with candidate key <code>{StudentID, CourseID}</code>:</i></p>\n        <p><code>CourseID &rarr; CourseName</code> is a partial dependency. Resolved by decomposing into: <code>Enrollment(StudentID, CourseID, Grade)</code> and <code>Course(CourseID, CourseName)</code>.</p>\n    </div>\n\n    <div class=\"info-box\">\n        <p class=\"step-label\">2. Third Normal Form (3NF):</p>\n        <ul>\n            <li><b>Condition 1:</b> Relation must already be in 2NF.</li>\n            <li><b>Condition 2:</b> <b>No Transitive Dependency:</b> Non-prime attributes must not depend on other non-prime attributes. For every non-trivial FD <code>X &rarr; Y</code>:\n                <ul>\n                    <li>Either <b>X is a Super Key</b>, OR</li>\n                    <li><b>Y is a Prime Attribute</b> (part of any candidate key).</li>\n                </ul>\n            </li>\n        </ul>\n        <p><i>Example: In <code>Employee(EmpId, EmpName, DeptId, DeptName)</code> where <code>EmpId &rarr; DeptId</code> and <code>DeptId &rarr; DeptName</code>:</i></p>\n        <p>Decompose into <code>Emp(EmpId, EmpName, DeptId)</code> and <code>Dept(DeptId, DeptName)</code>.</p>\n    </div>\n</div>\n\n<!-- ==================== SECTION C ==================== -->\n<div class=\"sec-title\">Section – C (Long Answer Questions &bull; 15 Marks Each &bull; Attempt Any Three)</div>\n\n<!-- Q9 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q9. Define Boyce-Codd Normal Form (BCNF). Compare 3NF and BCNF with a suitable example. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Boyce-Codd Normal Form (BCNF)</b> is a stricter, stronger version of 3NF. A relation R is in BCNF if and only if:</p>\n    <div class=\"info-box\">\n        <p>For every non-trivial Functional Dependency <code>X &rarr; Y</code> in R, <b>X MUST be a Super Key</b>.</p>\n    </div>\n    \n    <p class=\"step-label\">Key Difference between 3NF and BCNF:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Property</th>\n            <th style=\"width: 38%;\">Third Normal Form (3NF)</th>\n            <th style=\"width: 37%;\">Boyce-Codd Normal Form (BCNF)</th>\n        </tr>\n        <tr>\n            <td><b>Condition for X &rarr; Y</b></td>\n            <td>Valid if X is Super Key <b>OR</b> Y is a prime attribute.</td>\n            <td>Valid <b>ONLY</b> if X is a Super Key (no relaxation for prime Y).</td>\n        </tr>\n        <tr>\n            <td><b>Dependency Preservation</b></td>\n            <td>Always preserves all functional dependencies.</td>\n            <td>May occasionally sacrifice dependency preservation.</td>\n        </tr>\n        <tr>\n            <td><b>Redundancy Level</b></td>\n            <td>May retain slight redundancy for overlapping keys.</td>\n            <td>Strictly zero redundancy caused by functional dependencies.</td>\n        </tr>\n    </table>\n\n    <p class=\"step-label\">Classic Example Illustrating 3NF vs BCNF:</p>\n    <p>Consider relation <code>StudentAdvisor(StudentID, Subject, Advisor)</code> with business rules:</p>\n    <ul>\n        <li>A student can take multiple subjects and have an advisor for each: <code>{StudentID, Subject} &rarr; Advisor</code></li>\n        <li>Each advisor teaches only one subject: <code>Advisor &rarr; Subject</code></li>\n        <li>Candidate Keys: <code>{StudentID, Subject}</code> and <code>{StudentID, Advisor}</code>.</li>\n        <li>Prime Attributes: <code>StudentID</code>, <code>Subject</code>, <code>Advisor</code>.</li>\n    </ul>\n    <div class=\"info-box\">\n        <p><b>Check for 3NF:</b> For FD <code>Advisor &rarr; Subject</code>, Advisor is not a super key, but <b>Subject is a prime attribute</b>. Therefore, the table is in <b>3NF</b> &check;.</p>\n        <p><b>Check for BCNF:</b> In <code>Advisor &rarr; Subject</code>, Advisor is <b>NOT</b> a super key. Hence, this table <b>violates BCNF</b> &cross;.</p>\n        <p><b>BCNF Decomposition:</b> Split into two relations:</p>\n        <ol>\n            <li><code>AdvisorSubject(Advisor, Subject)</code> — Key: <code>Advisor</code> &check;</li>\n            <li><code>StudentAdvisor(StudentID, Advisor)</code> — Key: <code>{StudentID, Advisor}</code> &check;</li>\n        </ol>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q10 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q10. Explain Relational Algebra Fundamental Operations with examples. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Relational Algebra is a procedural query language consisting of operations that take one or two relations as input and produce a new relation as output.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 20%;\">Operation & Symbol</th>\n            <th style=\"width: 45%;\">Description & Formal Rule</th>\n            <th style=\"width: 35%;\">Concrete Example Expression</th>\n        </tr>\n        <tr>\n            <td><b>Selection (&sigma;)</b></td>\n            <td>Selects tuples that satisfy a given predicate condition. Acts as a horizontal filter.</td>\n            <td><code>&sigma;<sub>Marks &gt; 75</sub> (Student)</code><br>Filters students scoring above 75.</td>\n        </tr>\n        <tr>\n            <td><b>Projection (&pi;)</b></td>\n            <td>Selects specified attribute columns and automatically discards duplicate tuples. Vertical filter.</td>\n            <td><code>&pi;<sub>RollNo, Name</sub> (Student)</code><br>Extracts RollNo and Name columns.</td>\n        </tr>\n        <tr>\n            <td><b>Cartesian Product (&times;)</b></td>\n            <td>Combines each tuple of relation R with every tuple of relation S. Output size: <code>|R| &times; |S|</code>.</td>\n            <td><code>Student &times; Course</code></td>\n        </tr>\n        <tr>\n            <td><b>Union (&cup;)</b></td>\n            <td>Combines unique tuples from two union-compatible relations (identical arity and compatible domains).</td>\n            <td><code>&pi;<sub>Name</sub>(Faculty) &cup; &pi;<sub>Name</sub>(Student)</code></td>\n        </tr>\n        <tr>\n            <td><b>Set Difference (&minus;)</b></td>\n            <td>Returns tuples present in relation R but not in relation S (must be union-compatible).</td>\n            <td><code>&pi;<sub>RollNo</sub>(AllStudents) &minus; &pi;<sub>RollNo</sub>(Placed)</code></td>\n        </tr>\n        <tr>\n            <td><b>Rename (&rho;)</b></td>\n            <td>Renames a relation or its attributes to prevent ambiguities in self-joins.</td>\n            <td><code>&rho;<sub>S1</sub>(Student)</code></td>\n        </tr>\n        <tr>\n            <td><b>Natural Join (&bowtie;)</b></td>\n            <td>Equi-join combining Cartesian product, equality selection on common attributes, and duplicate column removal.</td>\n            <td><code>Student &bowtie; Department</code></td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q11 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q11. Explain SQL Characteristics and Five Aggregate Functions with SQL queries. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>SQL Characteristics:</b> SQL is a declarative, non-procedural language allowing users to specify <i>what</i> data is needed rather than <i>how</i> to retrieve it. It integrates DDL, DML, DCL, and TCL commands with full ACID compliance.</p>\n    \n    <p class=\"step-label\">Five Core Aggregate Functions (operating on Employee table):</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 15%;\">Function</th>\n            <th style=\"width: 35%;\">Purpose</th>\n            <th style=\"width: 50%;\">SQL Query Example & Description</th>\n        </tr>\n        <tr>\n            <td><code>COUNT()</code></td>\n            <td>Counts number of non-null values or total rows matching criteria.</td>\n            <td><code>SELECT COUNT(*) FROM Employee WHERE Dept = 'IT';</code><br>Returns total number of employees in IT department.</td>\n        </tr>\n        <tr>\n            <td><code>SUM()</code></td>\n            <td>Calculates total arithmetic sum of numeric values.</td>\n            <td><code>SELECT SUM(Salary) FROM Employee WHERE Dept = 'Sales';</code><br>Calculates total monthly payroll for Sales department.</td>\n        </tr>\n        <tr>\n            <td><code>AVG()</code></td>\n            <td>Calculates average mean value of numeric attribute.</td>\n            <td><code>SELECT AVG(Salary) FROM Employee;</code><br>Returns average company-wide employee salary.</td>\n        </tr>\n        <tr>\n            <td><code>MIN()</code></td>\n            <td>Returns smallest minimum value in the attribute set.</td>\n            <td><code>SELECT MIN(Salary) FROM Employee;</code><br>Finds the lowest compensation in the firm.</td>\n        </tr>\n        <tr>\n            <td><code>MAX()</code></td>\n            <td>Returns highest maximum value in the attribute set.</td>\n            <td><code>SELECT Dept, MAX(Salary) FROM Employee GROUP BY Dept;</code><br>Returns highest salary earned in each department.</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q12 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q12. Explain Concurrency Control and Two-Phase Locking (2PL) Protocol with its pitfalls. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Concurrency Control</b> coordinates simultaneous transaction execution to prevent conflicts (Lost Update, Uncommitted Read, Inconsistent Analysis) and ensure Serializable schedules.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">Two-Phase Locking (2PL) Protocol:</p>\n        <ol>\n            <li><b>Growing (Expansion) Phase:</b> Transaction may acquire locks (Shared <code>S-Lock</code> or Exclusive <code>X-Lock</code>) but <b>cannot release any lock</b>.</li>\n            <li><b>Lock Point:</b> The moment the transaction has acquired all necessary locks.</li>\n            <li><b>Shrinking (Contraction) Phase:</b> Transaction may release locks but <b>cannot acquire any new locks</b>.</li>\n        </ol>\n        <p><b>Theorem:</b> Any schedule following the 2PL protocol is guaranteed to be <b>Conflict Serializable</b>.</p>\n    </div>\n\n    <div class=\"info-box\">\n        <p class=\"step-label\">Pitfalls of Basic 2PL & Solutions:</p>\n        <ul>\n            <li>\n                <b>Cascading Aborts / Rollbacks:</b> If T1 releases a lock early in its shrinking phase and then aborts, any transaction T2 that read T1's dirty data must also abort.\n                <br><b>Solution &rarr; Strict 2PL:</b> All Exclusive (X) locks must be held until the transaction commits or aborts.\n            </li>\n            <li>\n                <b>Deadlocks:</b> 2PL does not prevent cyclic wait conditions where T1 holds Lock A waiting for Lock B, while T2 holds Lock B waiting for Lock A.\n                <br><b>Deadlock Handling Mechanisms:</b>\n                <ul>\n                    <li><i>Deadlock Detection:</i> Maintains a dynamic <b>Wait-For Graph (WFG)</b>; cycles indicate deadlock and trigger victim abort.</li>\n                    <li><i>Deadlock Prevention:</i> Uses transaction timestamps: <b>Wait-Die</b> (non-preemptive) or <b>Wound-Wait</b> (preemptive).</li>\n                </ul>\n            </li>\n        </ul>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q13 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q13. Write detailed notes on: (a) Three-Schema Architecture, (b) Data Independence, and (c) Role of DBA. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n\n    <p class=\"step-label\">(a) Three-Schema (ANSI/SPARC) Architecture:</p>\n    <div class=\"info-box\">\n        <ol>\n            <li><b>External Level (View Level):</b> Multiple tailored views for end-users and applications; conceals all irrelevant details and restricts unauthorized access.</li>\n            <li><b>Conceptual Level (Logical Level):</b> Community-wide global schema describing what data is stored, entities, relationships, attributes, and constraints (tables, primary/foreign keys).</li>\n            <li><b>Internal Level (Physical Level):</b> Physical data storage on disk, block allocation, record layout, B-Tree indexes, hashing, and encryption algorithms.</li>\n        </ol>\n    </div>\n\n    <p class=\"step-label\">(b) Data Independence:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Independence Level</th>\n            <th style=\"width: 45%;\">Definition & Mechanism</th>\n            <th style=\"width: 30%;\">Real-World Scenario</th>\n        </tr>\n        <tr>\n            <td><b>Physical Data Independence</b></td>\n            <td>Ability to alter physical schema (disk storage, indexes, RAID, hashing) without modifying logical/conceptual schema.</td>\n            <td>Adding a B-Tree index on <code>Salary</code> to boost search speed without altering table structure.</td>\n        </tr>\n        <tr>\n            <td><b>Logical Data Independence</b></td>\n            <td>Ability to alter conceptual schema (add tables, add columns) without modifying existing external schemas or application programs.</td>\n            <td>Adding a <code>PassportNo</code> column to Student table without breaking existing grade-card report queries.</td>\n        </tr>\n    </table>\n\n    <p class=\"step-label\">(c) Role and Responsibilities of Database Administrator (DBA):</p>\n    <ul>\n        <li><b>Schema Definition & Storage Structure:</b> Creates logical tables and allocates physical disk storage paths.</li>\n        <li><b>Security & Authorization:</b> Grants and revokes permissions (<code>GRANT</code>, <code>REVOKE</code>) to prevent data leaks.</li>\n        <li><b>Performance Tuning:</b> Monitors slow queries, builds indexes, and reorganizes partitions.</li>\n        <li><b>Backup & Disaster Recovery:</b> Schedules incremental/full backups and handles crash recovery using transaction logs.</li>\n    </ul>\n</div>"}, "java": {"code": "BCA-502", "paperCode": "18022", "title": "Java Programming & Web Design", "desc": "JVM Architecture, OOPs & Inheritance, Multithreading, Exception Handling, JDBC, Applets, Servlets, & TCP/IP Sockets.", "icon": "fa-code", "color": "amber", "pdfBank": "pdfs/BCA502_Java.pdf", "years": [{"year": "2025", "pdf": "pdfs/java_2025.pdf"}, {"year": "2024", "pdf": "pdfs/java_2024.pdf"}, {"year": "2023", "pdf": "pdfs/java_2023.pdf"}, {"year": "2021", "pdf": "pdfs/java_2021.pdf"}, {"year": "2020", "pdf": "pdfs/java_2020.pdf"}, {"year": "2019", "pdf": "pdfs/java_2019.pdf"}, {"year": "2018", "pdf": "pdfs/java_2018.pdf"}, {"year": "2017", "pdf": "pdfs/java_2017.pdf"}, {"year": "2016", "pdf": "pdfs/java_2016.pdf"}], "contentHtml": "<!-- ==================== SECTION A ==================== -->\n<div class=\"sec-title\">Section – A (Very Short Answer Questions &bull; 3 Marks Each &bull; All 5 Compulsory)</div>\n\n<!-- Q1 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q1. Why is Java called a Machine Independent language? <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Java achieves architecture neutrality through its two-stage compilation and execution process:</p>\n    <div class=\"info-box\">\n        <p><b>Compilation & Execution Workflow:</b></p>\n        <p><code>Source Code (.java) &rarr; javac Compiler &rarr; Intermediate Bytecode (.class) &rarr; JVM (Platform-Specific) &rarr; Machine Code</code></p>\n    </div>\n    <ul>\n        <li>Java source code is compiled into intermediate binary <b>Bytecode</b> rather than platform-specific machine code.</li>\n        <li>This bytecode can execute on any operating system (Windows, Linux, macOS) equipped with a suitable <b>Java Virtual Machine (JVM)</b>.</li>\n        <li>This fulfills the foundational Java paradigm: <b>\"Write Once, Run Anywhere\" (WORA)</b>.</li>\n    </ul>\n</div>\n\n<hr>\n\n<!-- Q2 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q2. Explain the functionality and architecture of JVM. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>The <b>Java Virtual Machine (JVM)</b> is an abstract computing machine that provides the runtime execution environment for compiled Java bytecode. It consists of three primary subsystems:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Subsystem</th>\n            <th style=\"width: 75%;\">Components & Core Responsibilities</th>\n        </tr>\n        <tr>\n            <td><b>1. Class Loader Subsystem</b></td>\n            <td>Responsible for <b>Loading</b> (.class files), <b>Linking</b> (Verification, Preparation of static memory, Resolution), and <b>Initialization</b> of static blocks and variables.</td>\n        </tr>\n        <tr>\n            <td><b>2. Runtime Data Areas</b></td>\n            <td>\n                &bull; <b>Method Area:</b> Stores class metadata, bytecode, static variables.<br>\n                &bull; <b>Heap Area:</b> Stores all dynamically instantiated objects and arrays.<br>\n                &bull; <b>JVM Stack:</b> Stores stack frames for method calls and local variables.<br>\n                &bull; <b>PC Registers:</b> Holds memory address of currently executing JVM instruction.<br>\n                &bull; <b>Native Method Stack:</b> Holds native C/C++ function call frames.\n            </td>\n        </tr>\n        <tr>\n            <td><b>3. Execution Engine</b></td>\n            <td>\n                &bull; <b>Interpreter:</b> Reads and executes bytecode instructions line by line.<br>\n                &bull; <b>JIT (Just-In-Time) Compiler:</b> Compiles frequently executed \"hotspots\" directly into native machine code to dramatically improve speed.<br>\n                &bull; <b>Garbage Collector (GC):</b> Automatically deallocates unreferenced heap memory.\n            </td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q3 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q3. Explain the 'super' keyword in Java with examples. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>In Java, <code>super</code> is a reference variable used by a subclass to refer directly to its immediate parent (superclass) object.</p>\n    <div class=\"info-box\">\n        <p><b>Three Distinct Usages of 'super':</b></p>\n        <ol>\n            <li><b>Refer to Hidden Parent Field:</b> <code>super.variableName;</code> resolves variable name collisions when the subclass shadows a parent field.</li>\n            <li><b>Invoke Overridden Parent Method:</b> <code>super.methodName();</code> allows a subclass method to explicitly invoke the original parent implementation.</li>\n            <li><b>Invoke Parent Constructor:</b> <code>super();</code> or <code>super(args);</code> calls the parent class constructor (must strictly be the <b>first statement</b> in the subclass constructor).</li>\n        </ol>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q4 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q4. Differentiate between Process-based and Thread-based Multitasking. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Comparison Criteria</th>\n            <th style=\"width: 38%;\">Process-based Multitasking</th>\n            <th style=\"width: 37%;\">Thread-based Multitasking</th>\n        </tr>\n        <tr>\n            <td><b>Definition & Scope</b></td>\n            <td>Executing two or more independent heavyweight programs concurrently (e.g., MS Word and Browser).</td>\n            <td>Executing two or more concurrent paths of execution within the <i>same</i> program.</td>\n        </tr>\n        <tr>\n            <td><b>Memory Allocation</b></td>\n            <td>Each process is allocated its own distinct, isolated private memory address space by the OS.</td>\n            <td>All threads belonging to the same process share identical memory address space and Heap memory.</td>\n        </tr>\n        <tr>\n            <td><b>Context-Switch Overhead</b></td>\n            <td>High overhead; OS must save registers, memory maps, and page tables.</td>\n            <td>Very low overhead; fast CPU register swap within shared process memory.</td>\n        </tr>\n        <tr>\n            <td><b>Communication Cost</b></td>\n            <td>Inter-Process Communication (IPC) is heavy and requires sockets, pipes, or shared files.</td>\n            <td>Inter-Thread Communication is fast and efficient using <code>wait()</code>, <code>notify()</code>, and shared variables.</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q5 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q5. Explain Anchor tag (&lt;a&gt;) and Table tag (&lt;table&gt;) in HTML. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <ul>\n        <li>\n            <b>Anchor Tag (<code>&lt;a&gt;</code>):</b> Creates clickable hyperlinks to navigate to external web pages, files, or internal bookmarks.\n            <div class=\"code-box\">&lt;a href=\"https://example.com/syllabus.html\" target=\"_blank\" title=\"View Syllabus\"&gt;Download Syllabus&lt;/a&gt;</div>\n            <i>Attributes:</i> <code>href</code> (target destination URL), <code>target=\"_blank\"</code> (opens in new tab), <code>download</code> (prompts download).\n        </li>\n        <li>\n            <b>Table Tag (<code>&lt;table&gt;</code>):</b> Organizes complex information into rows and columns.\n            <div class=\"code-box\">&lt;table border=\"1\" cellpadding=\"6\" cellspacing=\"0\"&gt;\n  &lt;tr&gt;&lt;th&gt;Roll No&lt;/th&gt;&lt;th&gt;Student Name&lt;/th&gt;&lt;th&gt;Marks&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;101&lt;/td&gt;&lt;td&gt;Amit Sharma&lt;/td&gt;&lt;td&gt;88&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</div>\n            <i>Tags:</i> <code>&lt;tr&gt;</code> (table row), <code>&lt;th&gt;</code> (header cell, bold and centered), <code>&lt;td&gt;</code> (data cell), <code>colspan</code> / <code>rowspan</code> (cell merging).\n        </li>\n    </ul>\n</div>\n\n<!-- ==================== SECTION B ==================== -->\n<div class=\"sec-title\">Section – B (Short Answer Questions &bull; 7.5 Marks Each &bull; Attempt Any Two)</div>\n\n<!-- Q6 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q6. What is an Exception? How do you handle multiple exceptions and use the finally block? <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>An <b>Exception</b> is an abnormal event occurring during program execution that disrupts the normal flow of instructions. Java provides robust exception handling using <code>try</code>, <code>catch</code>, <code>finally</code>, <code>throw</code>, and <code>throws</code>.</p>\n    <div class=\"info-box\">\n        <p><b>Rules for Handling Multiple Exceptions:</b> Specific subclasses of <code>Exception</code> must appear <i>before</i> generic parent exceptions; otherwise a compilation error (\"unreachable code\") occurs.</p>\n    </div>\n    <p class=\"step-label\">Complete Working Java Code:</p>\n    <div class=\"code-box\">public class MultiCatchFinallyDemo {\n    public static void main(String[] args) {\n        try {\n            int[] arr = {10, 20, 30};\n            int divisor = Integer.parseInt(args[0]); // May throw ArrayIndexOutOfBounds or NumberFormat\n            int result = arr[1] / divisor;           // May throw ArithmeticException if divisor == 0\n            System.out.println(\"Computed Result: \" + result);\n        } catch (ArithmeticException e) {\n            System.err.println(\"Error: Cannot divide by zero! \" + e.getMessage());\n        } catch (ArrayIndexOutOfBoundsException e) {\n            System.err.println(\"Error: Please provide a command-line argument!\");\n        } catch (NumberFormatException e) {\n            System.err.println(\"Error: Input must be a valid integer!\");\n        } catch (Exception e) {\n            System.err.println(\"Generic Fallback Exception caught: \" + e);\n        } finally {\n            // The finally block is GUARANTEED to execute regardless of whether an exception occurred or was handled\n            System.out.println(\"Finally block executed: Cleaned up system resources and closed streams.\");\n        }\n    }\n}</div>\n</div>\n\n<hr>\n\n<!-- Q7 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q7. Explain Applet Life Cycle and write a program to display an image. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>An <b>Applet</b> is a special Java program embedded in a web page and executed inside an applet viewer or Java-enabled browser. Its life cycle is managed by four lifecycle methods in <code>java.applet.Applet</code> plus the <code>paint()</code> method in <code>java.awt.Component</code>:</p>\n    <div class=\"info-box\">\n        <p><b>Applet Life Cycle Stages:</b></p>\n        <p><code>init() &rarr; start() &rarr; paint(Graphics g) &harr; stop() &rarr; destroy()</code></p>\n        <ul>\n            <li><code>init()</code>: Called once upon loading; initializes variables, fonts, and images.</li>\n            <li><code>start()</code>: Called after <code>init()</code> and whenever the browser revisits the page; starts animation/threads.</li>\n            <li><code>paint(Graphics g)</code>: Redraws applet UI whenever screen refresh is required.</li>\n            <li><code>stop()</code>: Called when user navigates away; suspends background threads.</li>\n            <li><code>destroy()</code>: Called prior to unloading; cleans up memory resources.</li>\n        </ul>\n    </div>\n    <p class=\"step-label\">Applet Code to Load and Display an Image:</p>\n    <div class=\"code-box\">import java.applet.Applet;\nimport java.awt.Graphics;\nimport java.awt.Image;\n\n/* &lt;applet code=\"ImageDisplayApplet.class\" width=\"400\" height=\"300\"&gt;&lt;/applet&gt; */\npublic class ImageDisplayApplet extends Applet {\n    private Image img;\n\n    @Override\n    public void init() {\n        // Load image from the directory hosting the HTML document\n        img = getImage(getDocumentBase(), \"logo.png\");\n    }\n\n    @Override\n    public void paint(Graphics g) {\n        // Draw image at (x=30, y=30) with original dimensions\n        g.drawImage(img, 30, 30, this);\n        g.drawString(\"CCSU BCA 5th Sem: Java Applet Image Rendering\", 30, 260);\n    }\n}</div>\n</div>\n\n<hr>\n\n<!-- Q8 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q8. Explain Threads and two ways to create Threads in Java. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>A <b>Thread</b> is a lightweight sub-process representing the smallest unit of dispatchable execution. In Java, multithreading is achieved through two standard mechanisms:</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">Approach 1: Extending the <code>java.lang.Thread</code> Class</p>\n        <div class=\"code-box\">class WorkerThread extends Thread {\n    @Override\n    public void run() {\n        for (int i = 1; i <= 3; i++) {\n            System.out.println(\"WorkerThread executing step \" + i + \" on: \" + Thread.currentThread().getName());\n        }\n    }\n}\n\npublic class ThreadDemo1 {\n    public static void main(String[] args) {\n        WorkerThread t1 = new WorkerThread();\n        t1.setName(\"Thread-Alpha\");\n        t1.start(); // Spawns new OS thread and invokes run()\n    }\n}</div>\n    </div>\n\n    <div class=\"info-box\">\n        <p class=\"step-label\">Approach 2: Implementing the <code>java.lang.Runnable</code> Interface (Recommended)</p>\n        <div class=\"code-box\">class WorkerTask implements Runnable {\n    @Override\n    public void run() {\n        for (int i = 1; i <= 3; i++) {\n            System.out.println(\"RunnableTask step \" + i + \" on: \" + Thread.currentThread().getName());\n        }\n    }\n}\n\npublic class ThreadDemo2 {\n    public static void main(String[] args) {\n        WorkerTask task = new WorkerTask();\n        Thread t2 = new Thread(task, \"Thread-Beta\");\n        t2.start();\n    }\n}</div>\n    </div>\n    <p><b>Key Advantage of Runnable:</b> Since Java allows single class inheritance, implementing <code>Runnable</code> frees the class to inherit from another domain superclass while still enabling multithreading.</p>\n</div>\n\n<!-- ==================== SECTION C ==================== -->\n<div class=\"sec-title\">Section – C (Long Answer Questions &bull; 15 Marks Each &bull; Attempt Any Three)</div>\n\n<!-- Q9 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q9. Illustrate Inheritance. Why is multiple inheritance not possible in Java? How is it implemented via Interfaces? <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Inheritance</b> is an Object-Oriented mechanism whereby a subclass automatically acquires fields and methods from a superclass using the <code>extends</code> keyword, fostering code reusability and polymorphism.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">The Diamond Problem (Why Multiple Class Inheritance is Prohibited):</p>\n        <p>If Class C inherits from both Class A and Class B, and both A and B define method <code>void display()</code> with different implementations: which version does an instance of Class C inherit? This ambiguity is known as the <b>Deadly Diamond of Death</b>. To avoid architectural complexity and pointer issues, Java designers disallowed multiple inheritance of classes.</p>\n    </div>\n\n    <p class=\"step-label\">Resolution using Interfaces:</p>\n    <p>Since interfaces contain only method declarations without state variables, there is zero ambiguity. A single Java class can implement multiple interfaces simultaneously.</p>\n    <div class=\"code-box\">interface Printable {\n    void print(); // Abstract contract\n}\n\ninterface Showable {\n    void show();\n}\n\n// Class implementing multiple interfaces\nclass DocumentReport implements Printable, Showable {\n    @Override\n    public void print() {\n        System.out.println(\"Printing document paper copy.\");\n    }\n\n    @Override\n    public void show() {\n        System.out.println(\"Showing document on digital screen.\");\n    }\n}\n\npublic class MultipleInheritanceDemo {\n    public static void main(String[] args) {\n        DocumentReport doc = new DocumentReport();\n        doc.print();\n        doc.show();\n    }\n}</div>\n</div>\n\n<hr>\n\n<!-- Q10 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q10. What is JDBC? Explain types of JDBC drivers. Write a program to insert and select records using PreparedStatement. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Java Database Connectivity (JDBC)</b> is a standard Java API (<code>java.sql</code> package) providing uniform, vendor-neutral database communication.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Driver Category</th>\n            <th style=\"width: 35%;\">Architecture & Mechanism</th>\n            <th style=\"width: 40%;\">Pros & Cons</th>\n        </tr>\n        <tr>\n            <td><b>Type-1: JDBC-ODBC Bridge</b></td>\n            <td>Translates JDBC calls into ODBC calls; requires native ODBC client installed.</td>\n            <td>Slow, platform-dependent, deprecated in modern Java.</td>\n        </tr>\n        <tr>\n            <td><b>Type-2: Native-API Driver</b></td>\n            <td>Converts JDBC calls directly into native C/C++ vendor client library calls.</td>\n            <td>Faster than Type-1, but requires native vendor client binaries on each machine.</td>\n        </tr>\n        <tr>\n            <td><b>Type-3: Network-Protocol Driver</b></td>\n            <td>Sends JDBC calls to an intermediate application server middleware.</td>\n            <td>Flexible, multi-database support, but adds server hop.</td>\n        </tr>\n        <tr>\n            <td><b>Type-4: Thin Driver (Pure Java)</b></td>\n            <td>Directly converts JDBC calls into database native network socket protocol.</td>\n            <td><b>Highest performance</b>, 100% pure Java, platform independent, no client installation.</td>\n        </tr>\n    </table>\n\n    <p class=\"step-label\">Complete JDBC Program (PreparedStatement Insert & Select):</p>\n    <div class=\"code-box\">import java.sql.Connection;\nimport java.sql.DriverManager;\nimport java.sql.PreparedStatement;\nimport java.sql.ResultSet;\n\npublic class JdbcPreparedStatementDemo {\n    public static void main(String[] args) {\n        String url = \"jdbc:mysql://localhost:3306/college_db\";\n        String user = \"root\";\n        String pass = \"password\";\n\n        try (Connection con = DriverManager.getConnection(url, user, pass)) {\n            // 1. Parameterized INSERT using PreparedStatement (Prevents SQL Injection)\n            String insertSql = \"INSERT INTO students (roll_no, name, marks) VALUES (?, ?, ?)\";\n            try (PreparedStatement psInsert = con.prepareStatement(insertSql)) {\n                psInsert.setInt(1, 105);\n                psInsert.setString(2, \"Vikas Verma\");\n                psInsert.setDouble(3, 91.5);\n                int rows = psInsert.executeUpdate();\n                System.out.println(\"Rows successfully inserted: \" + rows);\n            }\n\n            // 2. Querying data using PreparedStatement\n            String selectSql = \"SELECT roll_no, name, marks FROM students WHERE marks >= ?\";\n            try (PreparedStatement psSelect = con.prepareStatement(selectSql)) {\n                psSelect.setDouble(1, 75.0);\n                ResultSet rs = psSelect.executeQuery();\n                System.out.println(\"--- High Performing Students ---\");\n                while (rs.next()) {\n                    int rno = rs.getInt(\"roll_no\");\n                    String sname = rs.getString(\"name\");\n                    double scr = rs.getDouble(\"marks\");\n                    System.out.println(\"Roll: \" + rno + \" | Name: \" + sname + \" | Marks: \" + scr);\n                }\n            }\n        } catch (Exception e) {\n            e.printStackTrace();\n        }\n    }\n}</div>\n</div>\n\n<hr>\n\n<!-- Q11 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q11. Explain Servlets and their Life Cycle. Compare Servlets and JSP. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>A <b>Servlet</b> is a server-side Java class managed by a Servlet Container (e.g., Apache Tomcat) that receives client HTTP requests, processes business logic, and generates dynamic web responses.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">Servlet Life Cycle (javax.servlet.Servlet Interface):</p>\n        <ol>\n            <li><b>Loading & Instantiation:</b> Servlet class bytecode is loaded and a single instance is instantiated in container memory.</li>\n            <li><b>Initialization (<code>init(ServletConfig config)</code>):</b> Invoked <b>only once</b> immediately after instantiation; loads database connections and parameters.</li>\n            <li><b>Request Servicing (<code>service(ServletRequest, ServletResponse)</code>):</b> Dispatches each incoming request thread to handler methods (<code>doGet()</code> or <code>doPost()</code>). Runs concurrently on separate threads.</li>\n            <li><b>Destruction (<code>destroy()</code>):</b> Invoked <b>only once</b> when container shuts down or reloads; deallocates resources.</li>\n        </ol>\n    </div>\n\n    <p class=\"step-label\">Comparison: Servlets vs JavaServer Pages (JSP):</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Feature</th>\n            <th style=\"width: 38%;\">Servlets</th>\n            <th style=\"width: 37%;\">JSP (JavaServer Pages)</th>\n        </tr>\n        <tr>\n            <td><b>Core Paradigm</b></td>\n            <td>Pure Java code with embedded HTML written inside <code>out.println()</code> statements.</td>\n            <td>Standard HTML markup with embedded Java scriptlet tags (<code>&lt;% ... %&gt;</code>).</td>\n        </tr>\n        <tr>\n            <td><b>MVC Architectural Role</b></td>\n            <td>Best suited as <b>Controller</b> to manage request dispatching, validation, and business logic.</td>\n            <td>Best suited as <b>View</b> layer to present and format UI output for end users.</td>\n        </tr>\n        <tr>\n            <td><b>Compilation Speed</b></td>\n            <td>Pre-compiled into bytecode; executes rapidly from the very first request.</td>\n            <td>First-request is slower because JSP is internally translated into a Servlet and compiled.</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q12 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q12. Explain TCP/IP Socket Programming in Java with a client-server example. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Java Socket programming provides process-to-process communication across networks using the <code>java.net</code> package. TCP provides reliable, stream-oriented, full-duplex transmission.</p>\n    <div class=\"info-box\">\n        <p><b>Core Classes:</b></p>\n        <ul>\n            <li><code>java.net.ServerSocket</code>: Listens on a dedicated port and waits for incoming client requests via <code>accept()</code>.</li>\n            <li><code>java.net.Socket</code>: Connects to a remote server IP and port; provides <code>getInputStream()</code> and <code>getOutputStream()</code>.</li>\n        </ul>\n    </div>\n\n    <p class=\"step-label\">Server Application (ServerApp.java):</p>\n    <div class=\"code-box\">import java.io.*;\nimport java.net.*;\n\npublic class ServerApp {\n    public static void main(String[] args) throws IOException {\n        int port = 5000;\n        try (ServerSocket serverSocket = new ServerSocket(port)) {\n            System.out.println(\"Server listening on port \" + port + \"... Waiting for client...\");\n            try (Socket socket = serverSocket.accept()) { // Blocks until client connects\n                System.out.println(\"Client connected: \" + socket.getInetAddress());\n                BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));\n                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);\n\n                String clientMessage = in.readLine();\n                System.out.println(\"Received from client: \" + clientMessage);\n                out.println(\"Echo from Server: Hello, \" + clientMessage.toUpperCase());\n            }\n        }\n    }\n}</div>\n\n    <p class=\"step-label\">Client Application (ClientApp.java):</p>\n    <div class=\"code-box\">import java.io.*;\nimport java.net.*;\n\npublic class ClientApp {\n    public static void main(String[] args) throws IOException {\n        String host = \"127.0.0.1\";\n        int port = 5000;\n        try (Socket socket = new Socket(host, port)) {\n            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);\n            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));\n\n            out.println(\"CCSU BCA 5th Sem Student\");\n            String response = in.readLine();\n            System.out.println(\"Server response: \" + response);\n        }\n    }\n}</div>\n</div>\n\n<hr>\n\n<!-- Q13 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q13. Discuss Layout Managers in Java AWT/Swing (FlowLayout, BorderLayout, GridLayout, CardLayout, GridBagLayout). <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>A <b>Layout Manager</b> automatically computes the geometric sizing and spatial positioning of GUI components inside a container (such as <code>JFrame</code> or <code>JPanel</code>), abstracting away OS platform differences.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 20%;\">Layout Manager</th>\n            <th style=\"width: 50%;\">Spatial Arrangement Strategy</th>\n            <th style=\"width: 30%;\">Default Container & Behavior</th>\n        </tr>\n        <tr>\n            <td><b>FlowLayout</b></td>\n            <td>Arranges components sequentially in a horizontal line. When row width is exhausted, wraps automatically to next line.</td>\n            <td>Default for <code>JPanel</code>. Retains preferred component size.</td>\n        </tr>\n        <tr>\n            <td><b>BorderLayout</b></td>\n            <td>Divides container into 5 designated regions: <code>NORTH</code>, <code>SOUTH</code>, <code>EAST</code>, <code>WEST</code>, and <code>CENTER</code>. Components stretch to fill their region.</td>\n            <td>Default for <code>JFrame</code> and <code>JDialog</code>. Unused regions collapse into <code>CENTER</code>.</td>\n        </tr>\n        <tr>\n            <td><b>GridLayout</b></td>\n            <td>Arranges components in a strict two-dimensional matrix of equal-sized rectangular grid cells (rows &times; columns).</td>\n            <td>All components forced to identical width and height regardless of preferred size.</td>\n        </tr>\n        <tr>\n            <td><b>CardLayout</b></td>\n            <td>Stacks components on top of each other like a deck of playing cards. Only one component (card) is visible at a time.</td>\n            <td>Ideal for wizard installers, multi-tab dialogues, and step-by-step forms.</td>\n        </tr>\n        <tr>\n            <td><b>GridBagLayout</b></td>\n            <td>The most flexible and sophisticated layout manager. Components can vary in size and span multiple rows/columns using <code>GridBagConstraints</code>.</td>\n            <td>Allows precise, enterprise-grade responsive form alignment without nested panels.</td>\n        </tr>\n    </table>\n</div>"}, "networks": {"code": "BCA-503", "paperCode": "18023", "title": "Computer Networks", "desc": "OSI 7-Layer Architecture, TCP 3-Way Handshake, Subnetting/CIDR, Topologies, Leaky Bucket, Shannon Theorem, & Switching.", "icon": "fa-network-wired", "color": "emerald", "pdfBank": "pdfs/BCA503_Networks.pdf", "years": [{"year": "2025", "pdf": "pdfs/networks_2025.pdf"}, {"year": "2024", "pdf": "pdfs/networks_2024.pdf"}, {"year": "2023", "pdf": "pdfs/networks_2023.pdf"}, {"year": "2021", "pdf": "pdfs/networks_2021.pdf"}, {"year": "2020", "pdf": "pdfs/networks_2020.pdf"}, {"year": "2019", "pdf": "pdfs/networks_2019.pdf"}, {"year": "2018", "pdf": "pdfs/networks_2018.pdf"}, {"year": "2017", "pdf": "pdfs/networks_2017.pdf"}, {"year": "2016", "pdf": "pdfs/networks_2016.pdf"}], "contentHtml": "<!-- ==================== SECTION A ==================== -->\n<div class=\"sec-title\">Section – A (Very Short Answer Questions &bull; 3 Marks Each &bull; All 5 Compulsory)</div>\n\n<!-- Q1 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q1. Describe the various components of Data Communication. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Data communication is the exchange of data between two devices via a transmission medium. It comprises five essential components:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Component</th>\n            <th style=\"width: 75%;\">Description & Role</th>\n        </tr>\n        <tr>\n            <td><b>1. Message</b></td>\n            <td>The information or payload to be communicated (Text, Numbers, Pictures, Audio, Video).</td>\n        </tr>\n        <tr>\n            <td><b>2. Sender (Transmitter)</b></td>\n            <td>The source device originating and transmitting the data message (PC, Workstation, Smartphone).</td>\n        </tr>\n        <tr>\n            <td><b>3. Receiver</b></td>\n            <td>The destination device that receives the transmitted data (Server, Printer, Mobile terminal).</td>\n        </tr>\n        <tr>\n            <td><b>4. Transmission Medium</b></td>\n            <td>The physical communication conduit carrying the signal from sender to receiver: Guided (Twisted pair, Coaxial cable, Fiber optic) or Unguided (Radio waves, Microwaves, Infrared).</td>\n        </tr>\n        <tr>\n            <td><b>5. Protocol</b></td>\n            <td>A formal set of governing rules that coordinate data transmission syntax, semantics, and timing (e.g., TCP/IP, HTTP).</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q2 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q2. Define Bandwidth and Network Congestion. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <div class=\"info-box\">\n        <p class=\"step-label\">1. Bandwidth:</p>\n        <p>The maximum data transfer capacity of a communication channel over a given interval. In digital systems, it is measured in <b>bits per second (bps, Mbps, Gbps)</b>; in analog systems, it represents the frequency range (in Hertz, Hz) between upper and lower cutoff frequencies (<code>Bandwidth = f<sub>high</sub> &minus; f<sub>low</sub></code>).</p>\n    </div>\n    <div class=\"info-box\">\n        <p class=\"step-label\">2. Network Congestion:</p>\n        <p>A state where network nodes (routers/switches) carry more data packets than they can accommodate. When offered traffic load exceeds channel capacity, router queues overflow, causing <b>packet queuing delay, packet loss, and throughput collapse</b>.</p>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q3 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q3. Distinguish between MAC Address and IP Address. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Parameter</th>\n            <th style=\"width: 38%;\">MAC Address (Physical Address)</th>\n            <th style=\"width: 37%;\">IP Address (Logical Address)</th>\n        </tr>\n        <tr>\n            <td><b>OSI Layer</b></td>\n            <td>Data Link Layer (Layer 2).</td>\n            <td>Network Layer (Layer 3).</td>\n        </tr>\n        <tr>\n            <td><b>Address Length & Format</b></td>\n            <td><b>48 bits (6 bytes)</b>; written in 12 hexadecimal digits (e.g., <code>00:1A:2B:3C:4D:5E</code>).</td>\n            <td><b>32 bits</b> in IPv4 (e.g., <code>192.168.1.1</code>); <b>128 bits</b> in IPv6 (hexadecimal).</td>\n        </tr>\n        <tr>\n            <td><b>Permanence & Assignment</b></td>\n            <td>Permanently hard-coded into Network Interface Card (NIC) by manufacturer (OUI).</td>\n            <td>Dynamically (DHCP) or statically assigned based on network location.</td>\n        </tr>\n        <tr>\n            <td><b>Scope of Utility</b></td>\n            <td>Local node-to-node frame delivery within the same LAN segment.</td>\n            <td>Global end-to-end packet routing across multiple networks/Internet.</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q4 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q4. Differentiate between a Hub and a Switch. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Feature</th>\n            <th style=\"width: 38%;\">Network Hub</th>\n            <th style=\"width: 37%;\">Network Switch</th>\n        </tr>\n        <tr>\n            <td><b>Operating OSI Layer</b></td>\n            <td>Physical Layer (Layer 1).</td>\n            <td>Data Link Layer (Layer 2) / Multilayer (Layer 3).</td>\n        </tr>\n        <tr>\n            <td><b>Data Transmission Mode</b></td>\n            <td><b>Broadcasts</b> all incoming frames to every connected port indiscriminately.</td>\n            <td><b>Unicasts</b> frames selectively to the specific destination port using MAC table.</td>\n        </tr>\n        <tr>\n            <td><b>Collision Domains</b></td>\n            <td>All ports share a single collision domain (high collision risk).</td>\n            <td>Each individual port forms its own dedicated collision domain.</td>\n        </tr>\n        <tr>\n            <td><b>Bandwidth Sharing</b></td>\n            <td>Total bandwidth is shared among all connected active nodes.</td>\n            <td>Dedicated, full-rate bandwidth provided to each port (full-duplex).</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q5 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q5. What is Subnetting? Give an example with CIDR calculation. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Subnetting</b> is the practice of logically partitioning a single large IP network into smaller, distinct subnetworks (subnets) by borrowing host bits for the network ID. This reduces broadcast domains, improves routing efficiency, and conserves IP addresses.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"step-label\">Example: Subnetting 192.168.1.0/24 into 4 Subnets</p>\n        <ul>\n            <li>To create 4 subnets: Borrow 2 bits from host portion (<code>2<sup>2</sup> = 4</code> subnets).</li>\n            <li>New prefix length: <code>/24 + 2 = /26</code> &rArr; Subnet Mask: <code>255.255.255.192</code>.</li>\n            <li>Block Size: <code>256 &minus; 192 = 64</code> addresses per subnet (62 usable hosts).</li>\n        </ul>\n        <table class=\"data-table\">\n            <tr>\n                <th>Subnet #</th>\n                <th>Network ID</th>\n                <th>Usable Host IP Range</th>\n                <th>Directed Broadcast IP</th>\n            </tr>\n            <tr><td>Subnet 1</td><td><code>192.168.1.0</code></td><td><code>192.168.1.1 &ndash; 192.168.1.62</code></td><td><code>192.168.1.63</code></td></tr>\n            <tr><td>Subnet 2</td><td><code>192.168.1.64</code></td><td><code>192.168.1.65 &ndash; 192.168.1.126</code></td><td><code>192.168.1.127</code></td></tr>\n            <tr><td>Subnet 3</td><td><code>192.168.1.128</code></td><td><code>192.168.1.129 &ndash; 192.168.1.190</code></td><td><code>192.168.1.191</code></td></tr>\n            <tr><td>Subnet 4</td><td><code>192.168.1.192</code></td><td><code>192.168.1.193 &ndash; 192.168.1.254</code></td><td><code>192.168.1.255</code></td></tr>\n        </table>\n    </div>\n</div>\n\n<!-- ==================== SECTION B ==================== -->\n<div class=\"sec-title\">Section – B (Short Answer Questions &bull; 7.5 Marks Each &bull; Attempt Any Two)</div>\n\n<!-- Q6 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q6. Describe the role of the Transport Layer in the OSI Model. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>The <b>Transport Layer (Layer 4)</b> serves as the boundary between hardware-oriented subnet layers and software application layers, providing true <b>end-to-end, process-to-process reliable data delivery</b>.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Core Function</th>\n            <th style=\"width: 75%;\">Detailed Mechanism & Protocol Realization</th>\n        </tr>\n        <tr>\n            <td><b>1. Service-Point (Port) Addressing</b></td>\n            <td>Differentiates concurrent application processes executing on the same host using 16-bit Port numbers (e.g., HTTP: 80, HTTPS: 443, DNS: 53, SSH: 22).</td>\n        </tr>\n        <tr>\n            <td><b>2. Segmentation & Reassembly</b></td>\n            <td>Splits massive application messages into manageable chunks called <b>Segments</b>, appends sequence numbers, and reassembles them at receiver in exact order.</td>\n        </tr>\n        <tr>\n            <td><b>3. Connection Management</b></td>\n            <td>Manages connection-oriented transmission via 3-way handshake (TCP) or fast connectionless datagram delivery (UDP).</td>\n        </tr>\n        <tr>\n            <td><b>4. Flow Control</b></td>\n            <td>Uses <b>Sliding Window Protocol</b> to prevent a fast transmitter from overwhelming a slow receiver's buffer space.</td>\n        </tr>\n        <tr>\n            <td><b>5. Error Control</b></td>\n            <td>Enforces end-to-end integrity using 16-bit <b>Checksums</b> and Automatic Repeat reQuest (ARQ) retransmissions for dropped/corrupted segments.</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q7 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q7. Explain Network Topologies (Star, Mesh, Bus, Ring) with diagrams and comparisons. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Network Topology</b> defines the geometric and logical arrangement of communication links and nodes in a network.</p>\n    \n    <div class=\"diagram-card\">\n        <p class=\"step-label\">1. Star Topology:</p>\n        <p>All nodes connect via dedicated point-to-point links directly to a central multiport device (Hub or Switch).</p>\n        <p><i>Layout:</i> <code>[Node A, Node B, Node C, Node D] &rarr; [Central Switch / Hub]</code></p>\n        <p><b>Pros:</b> Easy to install, failure of one node does not impact others. <b>Cons:</b> Central hub is a single point of failure.</p>\n    </div>\n\n    <div class=\"diagram-card\">\n        <p class=\"step-label\">2. Mesh Topology (Full Mesh):</p>\n        <p>Every node has a dedicated point-to-point link to every other node in the network.</p>\n        <p><i>Link Formula:</i> For <code>n</code> nodes, requires <span class=\"frac\"><span class=\"num\">n(n &minus; 1)</span><span class=\"den\">2</span></span> physical links and <code>(n &minus; 1)</code> I/O ports per device.</p>\n        <p><b>Pros:</b> Maximum redundancy, zero traffic contention, highly fault-tolerant. <b>Cons:</b> Extremely expensive cabling and port requirements.</p>\n    </div>\n\n    <div class=\"diagram-card\">\n        <p class=\"step-label\">3. Bus Topology:</p>\n        <p>All nodes share a single common linear backbone cable (coaxial cable with terminators at both ends).</p>\n        <p><i>Layout:</i> <code>Terminator &mdash;&mdash; [Node 1] &mdash;&mdash; [Node 2] &mdash;&mdash; [Node 3] &mdash;&mdash; Terminator</code></p>\n        <p><b>Pros:</b> Minimal cabling needed. <b>Cons:</b> A single break in backbone takes down entire network; hard to troubleshoot.</p>\n    </div>\n\n    <div class=\"diagram-card\">\n        <p class=\"step-label\">4. Ring Topology:</p>\n        <p>Each device connects directly to its two immediate neighbors, forming a closed continuous loop.</p>\n        <p><i>Layout:</i> <code>Node 1 &rarr; Node 2 &rarr; Node 3 &rarr; Node 4 &rarr; Node 1 (Token Passing)</code></p>\n        <p><b>Pros:</b> Orderly token transmission, no collisions. <b>Cons:</b> Break in ring disrupts network (unless dual counter-rotating ring like FDDI is used).</p>\n    </div>\n</div>\n\n<hr>\n\n<!-- Q8 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q8. Explain Congestion Control Algorithms (Leaky Bucket and Token Bucket). <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>Traffic shaping algorithms regulate the bursty flow of packets injected into the network to mitigate congestion:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 25%;\">Parameter</th>\n            <th style=\"width: 38%;\">Leaky Bucket Algorithm</th>\n            <th style=\"width: 37%;\">Token Bucket Algorithm</th>\n        </tr>\n        <tr>\n            <td><b>Core Operating Principle</b></td>\n            <td>Bursty packet arrivals enter a finite buffer; packets leak out at a <b>strictly constant, rigid rate</b>.</td>\n            <td>Tokens generate into bucket at regular rate <code>r</code> up to capacity <code>C</code>. Packets transmit by consuming tokens.</td>\n        </tr>\n        <tr>\n            <td><b>Bursty Traffic Handling</b></td>\n            <td><b>Smooths out all bursts completely</b>; discards packets if bucket capacity overflows.</td>\n            <td><b>Allows controlled bursts</b> of packets up to the accumulated token capacity <code>C</code>.</td>\n        </tr>\n        <tr>\n            <td><b>Output Transmission Rate</b></td>\n            <td>Strictly uniform, deterministic constant rate regardless of burstiness.</td>\n            <td>Variable rate bounded by average rate <code>r</code> and peak burst capacity.</td>\n        </tr>\n        <tr>\n            <td><b>Packet Discard Policy</b></td>\n            <td>Discards incoming packets when buffer memory fills up.</td>\n            <td>Discards tokens when token bucket fills; packets queue or wait for fresh tokens.</td>\n        </tr>\n    </table>\n</div>\n\n<!-- ==================== SECTION C ==================== -->\n<div class=\"sec-title\">Section – C (Long Answer Questions &bull; 15 Marks Each &bull; Attempt Any Three)</div>\n\n<!-- Q9 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q9. Explain the TCP Three-Way Handshake with a sequence diagram. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>The <b>TCP 3-Way Handshake</b> is the synchronization mechanism used by Transmission Control Protocol to establish a reliable, full-duplex virtual connection between client and server before data exchange begins.</p>\n    \n    <div class=\"diagram-card\">\n        <p class=\"step-label\">TCP 3-Way Handshake Connection Sequence:</p>\n        <table class=\"data-table\">\n            <tr>\n                <th style=\"width: 15%;\">Step</th>\n                <th style=\"width: 20%;\">Direction</th>\n                <th style=\"width: 35%;\">Control Flags & Sequence #</th>\n                <th style=\"width: 30%;\">Action & Purpose</th>\n            </tr>\n            <tr>\n                <td><b>Step 1 (SYN)</b></td>\n                <td>Client &rarr; Server</td>\n                <td><code>SYN = 1</code><br><code>Seq = X</code> (Client ISN)</td>\n                <td>Client requests connection and announces its initial sequence number X. Client enters <b>SYN-SENT</b> state.</td>\n            </tr>\n            <tr>\n                <td><b>Step 2 (SYN-ACK)</b></td>\n                <td>Server &rarr; Client</td>\n                <td><code>SYN = 1, ACK = 1</code><br><code>Seq = Y</code> (Server ISN)<br><code>Ack_Num = X + 1</code></td>\n                <td>Server acknowledges client's request (<code>Ack = X + 1</code>) and provides its own sequence number Y. Server enters <b>SYN-RCVD</b>.</td>\n            </tr>\n            <tr>\n                <td><b>Step 3 (ACK)</b></td>\n                <td>Client &rarr; Server</td>\n                <td><code>ACK = 1</code><br><code>Seq = X + 1</code><br><code>Ack_Num = Y + 1</code></td>\n                <td>Client acknowledges server's sequence number (<code>Ack = Y + 1</code>). Connection enters <b>ESTABLISHED</b> state on both endpoints.</td>\n            </tr>\n        </table>\n    </div>\n    <p><b>Significance:</b> Guarantees both parties agree on initial sequence numbers, confirms bidirectional communication capability, and prevents old duplicate connection requests from causing false sessions.</p>\n</div>\n\n<hr>\n\n<!-- Q10 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q10. Draw and explain the 7 Layers of the ISO/OSI Reference Model. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p>The <b>Open Systems Interconnection (OSI)</b> reference model is a conceptual 7-layer architectural framework developed by ISO for standardized computer communication:</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 10%;\">Layer</th>\n            <th style=\"width: 18%;\">Layer Name</th>\n            <th style=\"width: 12%;\">PDU</th>\n            <th style=\"width: 38%;\">Primary Functions & Responsibilities</th>\n            <th style=\"width: 22%;\">Standard Protocols</th>\n        </tr>\n        <tr>\n            <td><b>Layer 7</b></td>\n            <td><b>Application</b></td>\n            <td>Data</td>\n            <td>Provides user interface and network service abstraction for software apps.</td>\n            <td>HTTP, HTTPS, FTP, SMTP, DNS, DHCP</td>\n        </tr>\n        <tr>\n            <td><b>Layer 6</b></td>\n            <td><b>Presentation</b></td>\n            <td>Data</td>\n            <td>Data syntax translation, compression, encryption and decryption (SSL/TLS).</td>\n            <td>JPEG, MPEG, ASCII, TLS/SSL</td>\n        </tr>\n        <tr>\n            <td><b>Layer 5</b></td>\n            <td><b>Session</b></td>\n            <td>Data</td>\n            <td>Dialog control, token management, session checkpointing and synchronization.</td>\n            <td>RPC, NetBIOS, PPTP</td>\n        </tr>\n        <tr>\n            <td><b>Layer 4</b></td>\n            <td><b>Transport</b></td>\n            <td>Segment</td>\n            <td>End-to-end process delivery, port addressing, flow control (sliding window), error recovery.</td>\n            <td>TCP, UDP</td>\n        </tr>\n        <tr>\n            <td><b>Layer 3</b></td>\n            <td><b>Network</b></td>\n            <td>Packet</td>\n            <td>Logical IP addressing, subnet routing, packet forwarding across networks.</td>\n            <td>IPv4, IPv6, ICMP, OSPF, BGP</td>\n        </tr>\n        <tr>\n            <td><b>Layer 2</b></td>\n            <td><b>Data Link</b></td>\n            <td>Frame</td>\n            <td>Node-to-node frame delivery, physical MAC addressing, CRC error detection, CSMA/CD.</td>\n            <td>Ethernet (802.3), Wi-Fi (802.11), PPP</td>\n        </tr>\n        <tr>\n            <td><b>Layer 1</b></td>\n            <td><b>Physical</b></td>\n            <td>Bit</td>\n            <td>Transmission of raw bitstream over physical media, signal encoding, voltages.</td>\n            <td>RS-232, RJ-45, V.35, Cables</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q11 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q11. Explain Shannon Capacity Theorem with a solved numerical problem. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Shannon's Capacity Theorem</b> establishes the theoretical upper limit on the maximum data transmission rate (Channel Capacity C) across a noisy communication channel with white Gaussian thermal noise.</p>\n    \n    <div class=\"info-box\">\n        <p class=\"math-formula\">\n            <b>Shannon Formula:</b>&emsp;\n            C = B &bull; log<sub>2</sub> &left;( 1 + <span class=\"frac\"><span class=\"num\">S</span><span class=\"den\">N</span></span> &right;) &nbsp; (in bits per second, bps)\n        </p>\n        <p>Where:</p>\n        <ul>\n            <li><code>C</code> = Maximum theoretical channel capacity in bits per second (bps)</li>\n            <li><code>B</code> = Channel bandwidth in Hertz (Hz)</li>\n            <li><code>S / N</code> = Signal-to-Noise Ratio (SNR as a linear power ratio)</li>\n        </ul>\n    </div>\n\n    <p class=\"step-label\">Solved Numerical Problem:</p>\n    <div class=\"info-box\">\n        <p><b>Problem Statement:</b> A noisy telephone channel has a bandwidth of <i>B = 3000 Hz</i> and a Signal-to-Noise Ratio of <i>SNR<sub>dB</sub> = 35 dB</i>. Calculate the theoretical maximum channel capacity.</p>\n        <p><b>Step 1: Convert SNR from decibels (dB) to linear ratio:</b></p>\n        <p class=\"math-formula\">\n            SNR<sub>dB</sub> = 10 &bull; log<sub>10</sub>(S/N) = 35 &rArr; log<sub>10</sub>(S/N) = 3.5 &rArr; <span class=\"frac\"><span class=\"num\">S</span><span class=\"den\">N</span></span> = 10<sup>3.5</sup> &approx; <b>3162.28</b>\n        </p>\n        <p><b>Step 2: Apply Shannon's Formula:</b></p>\n        <p class=\"math-formula\">\n            C = 3000 &bull; log<sub>2</sub>(1 + 3162.28) = 3000 &bull; log<sub>2</sub>(3163.28)\n        </p>\n        <p class=\"math-formula\">\n            Using change of base:&emsp; log<sub>2</sub>(3163.28) = <span class=\"frac\"><span class=\"num\">log<sub>10</sub>(3163.28)</span><span class=\"den\">log<sub>10</sub>(2)</span></span> = <span class=\"frac\"><span class=\"num\">3.50014</span><span class=\"den\">0.30103</span></span> &approx; <b>11.6272</b>\n        </p>\n        <p class=\"math-formula\">\n            C = 3000 &times; 11.6272 &approx; <b>34,881.6 bps &approx; 34.88 kbps</b>\n        </p>\n    </div>\n    <div><span class=\"highlight-ans\">Theoretical Channel Capacity: C &approx; 34.88 kbps</span></div>\n</div>\n\n<hr>\n\n<!-- Q12 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q12. Explain CSMA/CD in Ethernet and compare with CSMA/CA in Wi-Fi. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Carrier Sense Multiple Access (CSMA)</b> protocols require nodes to \"listen before talking\" on a shared broadcast transmission medium.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 22%;\">Comparison Feature</th>\n            <th style=\"width: 39%;\">CSMA/CD (Collision Detection)</th>\n            <th style=\"width: 39%;\">CSMA/CA (Collision Avoidance)</th>\n        </tr>\n        <tr>\n            <td><b>Standard & Medium</b></td>\n            <td>IEEE 802.3 (Wired Ethernet cables).</td>\n            <td>IEEE 802.11 (Wireless Wi-Fi radio channels).</td>\n        </tr>\n        <tr>\n            <td><b>Collision Strategy</b></td>\n            <td>Transmits while listening; if collision signal is detected, stops immediately.</td>\n            <td>Avoids collisions prior to transmission via reservation handshakes and delays.</td>\n        </tr>\n        <tr>\n            <td><b>Collision Response</b></td>\n            <td>Transmits a <b>Jam Signal</b> to notify all stations, then applies <b>Binary Exponential Backoff</b>.</td>\n            <td>Cannot detect collision while sending (half-duplex RF); infers collision if no ACK received.</td>\n        </tr>\n        <tr>\n            <td><b>Control Mechanism</b></td>\n            <td>Collision detection hardware listening for elevated cable voltage.</td>\n            <td><b>RTS (Request to Send) / CTS (Clear to Send)</b> handshakes + Inter-Frame Spacing (DIFS/SIFS).</td>\n        </tr>\n    </table>\n</div>\n\n<hr>\n\n<!-- Q13 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q13. Compare Circuit Switching, Packet Switching, and Message Switching. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Answer:</strong></p>\n    <p><b>Switching</b> is the methodology by which nodes communicate across multiple intermediate network nodes without direct point-to-point physical links.</p>\n    <table class=\"data-table\">\n        <tr>\n            <th style=\"width: 18%;\">Feature</th>\n            <th style=\"width: 28%;\">Circuit Switching</th>\n            <th style=\"width: 27%;\">Packet Switching</th>\n            <th style=\"width: 27%;\">Message Switching</th>\n        </tr>\n        <tr>\n            <td><b>Dedicated Physical Path</b></td>\n            <td><b>Yes</b>; dedicated end-to-end copper/fiber circuit reserved for session duration.</td>\n            <td><b>No</b>; dynamic independent packet routing over shared virtual links.</td>\n            <td><b>No</b>; whole message hops from node to node across shared lines.</td>\n        </tr>\n        <tr>\n            <td><b>Call Setup Phase</b></td>\n            <td>Required prior to any data transmission. Adds initial setup latency.</td>\n            <td>Zero connection setup latency (in Connectionless Datagram mode).</td>\n            <td>No setup phase needed.</td>\n        </tr>\n        <tr>\n            <td><b>Bandwidth Utilization</b></td>\n            <td>Low/wasteful; reserved circuit capacity is idle during conversational silence.</td>\n            <td><b>Very High</b>; dynamic statistical multiplexing shares channel bandwidth.</td>\n            <td>Moderate; links occupied only while whole message transmits.</td>\n        </tr>\n        <tr>\n            <td><b>Store & Forward Mechanism</b></td>\n            <td>None; continuous real-time bitstream.</td>\n            <td>Packets buffered at each router and forwarded. Minimal latency.</td>\n            <td>Entire message buffered on intermediate disks; very high delay.</td>\n        </tr>\n        <tr>\n            <td><b>Primary Application</b></td>\n            <td>Traditional Landline Telephony (PSTN), cellular voice calls.</td>\n            <td><b>The Modern Internet (IP)</b>, VoIP, streaming, web browsing.</td>\n            <td>Telegraph, Telex, historic military communication systems.</td>\n        </tr>\n    </table>\n</div>"}, "numerical": {"code": "BCA-504", "paperCode": "18024", "title": "Numerical Methods", "desc": "Bisection, Newton-Raphson, Regula-Falsi, Gauss Elimination, Gauss-Seidel, Simpson 1/3 & 3/8, Runge-Kutta 4th Order, & Picard.", "icon": "fa-calculator", "color": "indigo", "pdfBank": "pdfs/BCA504_Numerical.pdf", "years": [{"year": "2024", "pdf": "pdfs/nm_2024.pdf"}, {"year": "2023", "pdf": "pdfs/nm_2023.pdf"}, {"year": "2022", "pdf": "pdfs/nm_2022.pdf"}, {"year": "2021", "pdf": "pdfs/nm_2021.pdf"}, {"year": "2020", "pdf": "pdfs/nm_2020.pdf"}, {"year": "2019", "pdf": "pdfs/nm_2019.pdf"}, {"year": "2018", "pdf": "pdfs/nm_2018.pdf"}], "contentHtml": "<!-- ==================== SECTION A ==================== -->\n<div class=\"sec-title\">Section – A (Very Short Answer Questions &bull; 3 Marks Each &bull; All 5 Compulsory)</div>\n\n<!-- Q1 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q1. Obtain a real root of the equation <i>f(x) = x<sup>3</sup> + x<sup>2</sup> &minus; 1 = 0</i> using Bisection method correct to 3 decimal places. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Let <i>f(x) = x<sup>3</sup> + x<sup>2</sup> &minus; 1</i>.</p>\n    <ul>\n        <li>For <i>x = 0</i>: <i>f(0) = 0 + 0 &minus; 1 = &minus;1 &lt; 0</i></li>\n        <li>For <i>x = 1</i>: <i>f(1) = 1 + 1 &minus; 1 = +1 &gt; 0</i></li>\n    </ul>\n    <p>Since <i>f(0) &bull; f(1) &lt; 0</i>, a real root lies in the open interval <b>(0, 1)</b>.</p>\n    \n    <table class=\"iter-table\">\n        <tr>\n            <th>n</th><th>a</th><th>b</th><th>c = (a+b)/2</th><th>f(c)</th><th>Sign</th><th>Updated Interval</th>\n        </tr>\n        <tr><td>1</td><td>0.0000</td><td>1.0000</td><td>0.5000</td><td>&minus;0.6250</td><td>Negative (&lt; 0)</td><td>[0.5000, 1.0000]</td></tr>\n        <tr><td>2</td><td>0.5000</td><td>1.0000</td><td>0.7500</td><td>&minus;0.0156</td><td>Negative (&lt; 0)</td><td>[0.7500, 1.0000]</td></tr>\n        <tr><td>3</td><td>0.7500</td><td>1.0000</td><td>0.8750</td><td>+0.4355</td><td>Positive (&gt; 0)</td><td>[0.7500, 0.8750]</td></tr>\n        <tr><td>4</td><td>0.7500</td><td>0.8750</td><td>0.8125</td><td>+0.1965</td><td>Positive (&gt; 0)</td><td>[0.7500, 0.8125]</td></tr>\n        <tr><td>5</td><td>0.7500</td><td>0.8125</td><td>0.7812</td><td>+0.0872</td><td>Positive (&gt; 0)</td><td>[0.7500, 0.7812]</td></tr>\n        <tr><td>6</td><td>0.7500</td><td>0.7812</td><td>0.7656</td><td>+0.0350</td><td>Positive (&gt; 0)</td><td>[0.7500, 0.7656]</td></tr>\n        <tr><td>7</td><td>0.7500</td><td>0.7656</td><td>0.7578</td><td>+0.0095</td><td>Positive (&gt; 0)</td><td>[0.7500, 0.7578]</td></tr>\n        <tr><td>8</td><td>0.7500</td><td>0.7578</td><td>0.7539</td><td>&minus;0.0031</td><td>Negative (&lt; 0)</td><td>[0.7539, 0.7578]</td></tr>\n        <tr><td>9</td><td>0.7539</td><td>0.7578</td><td>0.7559</td><td>+0.0032</td><td>Positive (&gt; 0)</td><td>[0.7539, 0.7559]</td></tr>\n        <tr><td>10</td><td>0.7539</td><td>0.7559</td><td>0.7549</td><td>+0.00002</td><td>Positive (&ge; 0)</td><td>[0.7539, 0.7549]</td></tr>\n        <tr><td>11</td><td>0.7539</td><td>0.7549</td><td>0.7544</td><td>&minus;0.0015</td><td>Negative (&lt; 0)</td><td>[0.7544, 0.7549]</td></tr>\n    </table>\n    <p>At iteration 11, interval width is <i>|0.7549 &minus; 0.7544| = 0.0005 &lt; 0.001</i>.</p>\n    <div><span class=\"highlight-ans\">Final Converged Root: x &approx; 0.755 (correct to 3 decimal places)</span></div>\n</div>\n\n<hr>\n\n<!-- Q2 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q2. Define backward differences and prove the operator identity <i>E&nabla; = &nabla;E = &Delta;</i>. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p><strong>Definition:</strong> For equispaced points <i>x<sub>i</sub> = x<sub>0</sub> + i&bull;h</i>, the <b>Backward Difference Operator (&nabla;)</b> is defined as:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">&nabla;y<sub>i</sub> = y<sub>i</sub> &minus; y<sub>i&minus;1</sub> &emsp;and&emsp; &nabla;<sup>k</sup>y<sub>i</sub> = &nabla;<sup>k&minus;1</sup>y<sub>i</sub> &minus; &nabla;<sup>k&minus;1</sup>y<sub>i&minus;1</sub> &nbsp;(k &ge; 2)</p>\n    </div>\n    <p><strong>Backward Difference Table for ordered pairs (x<sub>0</sub>, y<sub>0</sub>) to (x<sub>4</sub>, y<sub>4</sub>):</strong></p>\n    <table class=\"iter-table\">\n        <tr><th>x</th><th>y</th><th>&nabla;y</th><th>&nabla;<sup>2</sup>y</th><th>&nabla;<sup>3</sup>y</th><th>&nabla;<sup>4</sup>y</th></tr>\n        <tr><td>x<sub>0</sub></td><td>y<sub>0</sub></td><td>—</td><td>—</td><td>—</td><td>—</td></tr>\n        <tr><td>x<sub>1</sub></td><td>y<sub>1</sub></td><td>&nabla;y<sub>1</sub> = y<sub>1</sub> &minus; y<sub>0</sub></td><td>—</td><td>—</td><td>—</td></tr>\n        <tr><td>x<sub>2</sub></td><td>y<sub>2</sub></td><td>&nabla;y<sub>2</sub> = y<sub>2</sub> &minus; y<sub>1</sub></td><td>&nabla;<sup>2</sup>y<sub>2</sub></td><td>—</td><td>—</td></tr>\n        <tr><td>x<sub>3</sub></td><td>y<sub>3</sub></td><td>&nabla;y<sub>3</sub> = y<sub>3</sub> &minus; y<sub>2</sub></td><td>&nabla;<sup>2</sup>y<sub>3</sub></td><td>&nabla;<sup>3</sup>y<sub>3</sub></td><td>—</td></tr>\n        <tr><td>x<sub>4</sub></td><td>y<sub>4</sub></td><td>&nabla;y<sub>4</sub> = y<sub>4</sub> &minus; y<sub>3</sub></td><td>&nabla;<sup>2</sup>y<sub>4</sub></td><td>&nabla;<sup>3</sup>y<sub>4</sub></td><td>&nabla;<sup>4</sup>y<sub>4</sub></td></tr>\n    </table>\n    <p><strong>Operator Proofs:</strong></p>\n    <ol>\n        <li><i>E &bull; &nabla; f(x) = E [f(x) &minus; f(x &minus; h)] = f(x + h) &minus; f(x) = &Delta;f(x) &rArr; <b>E&nabla; = &Delta;</b></i></li>\n        <li><i>&nabla; &bull; E f(x) = &nabla; [f(x + h)] = f(x + h) &minus; f(x) = &Delta;f(x) &rArr; <b>&nabla;E = &Delta;</b></i></li>\n    </ol>\n    <div><span class=\"highlight-ans\">Hence Proved: E&nabla; = &nabla;E = &Delta;</span></div>\n</div>\n\n<hr>\n\n<!-- Q3 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q3. Find the value of <span class=\"frac\"><span class=\"num\">dy</span><span class=\"den\">dx</span></span> at <i>x = 1.2</i> for points (1.0, 2.7183), (1.2, 3.3201), (1.4, 4.0552)... <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Given step size <i>h = 1.2 &minus; 1.0 = 0.2</i>. Let <i>x<sub>0</sub> = 1.2, y<sub>0</sub> = 3.3201</i>.</p>\n    <p>Neighbors: <i>x<sub>&minus;1</sub> = 1.0, y<sub>&minus;1</sub> = 2.7183</i> and <i>x<sub>1</sub> = 1.4, y<sub>1</sub> = 4.0552</i>.</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Central Difference Formula (First Derivative):</b><br>\n            f'(x<sub>0</sub>) &approx; <span class=\"frac\"><span class=\"num\">y<sub>1</sub> &minus; y<sub>&minus;1</sub></span><span class=\"den\">2h</span></span>\n        </p>\n        <p class=\"formula\">\n            f'(1.2) = <span class=\"frac\"><span class=\"num\">4.0552 &minus; 2.7183</span><span class=\"den\">2(0.2)</span></span>\n            = <span class=\"frac\"><span class=\"num\">1.3369</span><span class=\"den\">0.40</span></span>\n            = <b>3.34225</b>\n        </p>\n    </div>\n    <p><i>(Newton's Forward Difference check: f'(1.2) &approx; (1/0.2)[0.7351 &minus; 0.5(0.1627) + (1/3)(0.0361)] = 3.3289. True derivative e<sup>1.2</sup> &approx; 3.3201.)</i></p>\n    <div><span class=\"highlight-ans\">dy/dx at x = 1.2 is 3.34225</span></div>\n</div>\n\n<hr>\n\n<!-- Q4 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q4. Solve the following linear system using Gauss Elimination method: <span class=\"q-marks\">[3 Marks]</span></div>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            10x + y + z = 12<br>\n            2x + 10y + z = 13<br>\n            x + y + 3z = 5\n        </p>\n    </div>\n    <p><strong>Solution:</strong></p>\n    <p class=\"step-label\">Step 1: Form the Augmented Matrix [A | B]:</p>\n    <div style=\"text-align: center; margin: 4px 0;\">\n        <table class=\"matrix\">\n            <tr><td>10</td><td>1</td><td>1</td><td class=\"divider\">12</td></tr>\n            <tr><td>2</td><td>10</td><td>1</td><td class=\"divider\">13</td></tr>\n            <tr><td>1</td><td>1</td><td>3</td><td class=\"divider\">5</td></tr>\n        </table>\n    </div>\n    <p class=\"step-label\">Step 2: Forward Elimination to Upper Triangular Form:</p>\n    <ul>\n        <li><i>R<sub>2</sub> &rarr; R<sub>2</sub> &minus; (2/10)R<sub>1</sub> = R<sub>2</sub> &minus; 0.2R<sub>1</sub></i> &rArr; [0, 9.8, 0.8 | 10.6]</li>\n        <li><i>R<sub>3</sub> &rarr; R<sub>3</sub> &minus; (1/10)R<sub>1</sub> = R<sub>3</sub> &minus; 0.1R<sub>1</sub></i> &rArr; [0, 0.9, 2.9 | 3.8]</li>\n        <li><i>R<sub>3</sub> &rarr; R<sub>3</sub> &minus; (0.9 / 9.8)R<sub>2</sub></i> &rArr; [0, 0, 2.82653 | 2.82653]</li>\n    </ul>\n    <div style=\"text-align: center; margin: 4px 0;\">\n        <table class=\"matrix\">\n            <tr><td>10</td><td>1</td><td>1</td><td class=\"divider\">12</td></tr>\n            <tr><td>0</td><td>9.8</td><td>0.8</td><td class=\"divider\">10.6</td></tr>\n            <tr><td>0</td><td>0</td><td>2.82653</td><td class=\"divider\">2.82653</td></tr>\n        </table>\n    </div>\n    <p class=\"step-label\">Step 3: Back Substitution:</p>\n    <ul>\n        <li>From Row 3: 2.82653 &bull; z = 2.82653 &rArr; <b>z = 1</b></li>\n        <li>From Row 2: 9.8 &bull; y + 0.8(1) = 10.6 &rArr; 9.8 &bull; y = 9.8 &rArr; <b>y = 1</b></li>\n        <li>From Row 1: 10 &bull; x + 1(1) + 1(1) = 12 &rArr; 10 &bull; x = 10 &rArr; <b>x = 1</b></li>\n    </ul>\n    <div><span class=\"highlight-ans\">Unique Solution: x = 1, &nbsp; y = 1, &nbsp; z = 1</span></div>\n</div>\n\n<hr>\n\n<!-- Q5 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q5. Solve <span class=\"frac\"><span class=\"num\">dy</span><span class=\"den\">dx</span></span> = x + y<sup>2</sup>, with y(0) = 1 using Picard's method up to second approximation. <span class=\"q-marks\">[3 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Picard's Successive Approximation Formula:</b><br>\n            y<sup>(n)</sup>(x) = y<sub>0</sub> + &int;<sub>x<sub>0</sub></sub><sup>x</sup> f(t, y<sup>(n&minus;1)</sup>(t)) dt\n        </p>\n    </div>\n    <p>Given initial conditions: <i>x<sub>0</sub> = 0, y<sub>0</sub> = 1</i>, and <i>f(t, y) = t + y<sup>2</sup></i>.</p>\n    <p class=\"step-label\">First Approximation (y<sup>(1)</sup>):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            y<sup>(1)</sup>(x) = 1 + &int;<sub>0</sub><sup>x</sup> (t + 1<sup>2</sup>) dt\n            = 1 + [ <span class=\"frac\"><span class=\"num\">t<sup>2</sup></span><span class=\"den\">2</span></span> + t ]<sub>0</sub><sup>x</sup>\n            = <b>1 + x + <span class=\"frac\"><span class=\"num\">x<sup>2</sup></span><span class=\"den\">2</span></span></b>\n        </p>\n    </div>\n    <p class=\"step-label\">Second Approximation (y<sup>(2)</sup>):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            y<sup>(2)</sup>(x) = 1 + &int;<sub>0</sub><sup>x</sup> [ t + (1 + t + <span class=\"frac\"><span class=\"num\">t<sup>2</sup></span><span class=\"den\">2</span></span>)<sup>2</sup> ] dt\n        </p>\n        <p class=\"formula\">\n            Expand:&emsp; (1 + t + <span class=\"frac\"><span class=\"num\">t<sup>2</sup></span><span class=\"den\">2</span></span>)<sup>2</sup> = 1 + 2t + 2t<sup>2</sup> + t<sup>3</sup> + <span class=\"frac\"><span class=\"num\">t<sup>4</sup></span><span class=\"den\">4</span></span>\n        </p>\n        <p class=\"formula\">\n            Integrand = t + 1 + 2t + 2t<sup>2</sup> + t<sup>3</sup> + <span class=\"frac\"><span class=\"num\">t<sup>4</sup></span><span class=\"den\">4</span></span> = 1 + 3t + 2t<sup>2</sup> + t<sup>3</sup> + <span class=\"frac\"><span class=\"num\">t<sup>4</sup></span><span class=\"den\">4</span></span>\n        </p>\n        <p class=\"formula\">\n            y<sup>(2)</sup>(x) = 1 + [ t + <span class=\"frac\"><span class=\"num\">3t<sup>2</sup></span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">2t<sup>3</sup></span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">t<sup>4</sup></span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">t<sup>5</sup></span><span class=\"den\">20</span></span> ]<sub>0</sub><sup>x</sup>\n        </p>\n        <p class=\"formula\">\n            <b>y<sup>(2)</sup>(x) = 1 + x + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x<sup>2</sup> + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>x<sup>3</sup> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span>x<sup>4</sup> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span>x<sup>5</sup></b>\n        </p>\n    </div>\n    <div><span class=\"highlight-ans\">y<sup>(1)</sup> = 1 + x + x<sup>2</sup>/2 &emsp;|&emsp; y<sup>(2)</sup> = 1 + x + (3/2)x<sup>2</sup> + (2/3)x<sup>3</sup> + (1/4)x<sup>4</sup> + (1/20)x<sup>5</sup></span></div>\n</div>\n\n<!-- ==================== SECTION B ==================== -->\n<div class=\"sec-title\">Section – B (Short Answer Questions &bull; 7.5 Marks Each &bull; Attempt Any Two)</div>\n\n<!-- Q6 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q6. Find a real root of the equation <i>2x = log<sub>10</sub>(x) + 7</i> between 3 and 4 using Method of False Position (Regula Falsi). <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Let <i>f(x) = 2x &minus; log<sub>10</sub>(x) &minus; 7 = 0</i>.</p>\n    <ul>\n        <li>For <i>x<sub>0</sub> = 3</i>: <i>f(3) = 2(3) &minus; log<sub>10</sub>(3) &minus; 7 = 6 &minus; 0.47712 &minus; 7 = &minus;1.47712 &lt; 0</i></li>\n        <li>For <i>x<sub>1</sub> = 4</i>: <i>f(4) = 2(4) &minus; log<sub>10</sub>(4) &minus; 7 = 8 &minus; 0.60206 &minus; 7 = +0.39794 &gt; 0</i></li>\n    </ul>\n    <p>Since <i>f(3)</i> and <i>f(4)</i> have opposite signs, the root lies in the interval <b>(3, 4)</b>.</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Regula Falsi Iteration Formula:</b><br>\n            x<sub>2</sub> = <span class=\"frac\"><span class=\"num\">x<sub>0</sub> &bull; f(x<sub>1</sub>) &minus; x<sub>1</sub> &bull; f(x<sub>0</sub>)</span><span class=\"den\">f(x<sub>1</sub>) &minus; f(x<sub>0</sub>)</span></span>\n        </p>\n    </div>\n    <p class=\"step-label\">Iteration 1:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            x<sub>2</sub> = <span class=\"frac\"><span class=\"num\">3(0.39794) &minus; 4(&minus;1.47712)</span><span class=\"den\">0.39794 &minus; (&minus;1.47712)</span></span>\n            = <span class=\"frac\"><span class=\"num\">1.19382 + 5.90848</span><span class=\"den\">1.87506</span></span>\n            = <span class=\"frac\"><span class=\"num\">7.10230</span><span class=\"den\">1.87506</span></span>\n            &approx; <b>3.78777</b>\n        </p>\n    </div>\n    <p>Evaluate <i>f(x<sub>2</sub>)</i>:</p>\n    <p><i>f(3.78777) = 2(3.78777) &minus; log<sub>10</sub>(3.78777) &minus; 7 = 7.57554 &minus; 0.57838 &minus; 7 = &minus;0.00284 &lt; 0</i>.</p>\n    <p>Root lies in <b>[3.78777, 4.00000]</b>.</p>\n    <p class=\"step-label\">Iteration 2:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            x<sub>3</sub> = <span class=\"frac\"><span class=\"num\">3.78777(0.39794) &minus; 4(&minus;0.00284)</span><span class=\"den\">0.39794 &minus; (&minus;0.00284)</span></span>\n            = <span class=\"frac\"><span class=\"num\">1.50731 + 0.01136</span><span class=\"den\">0.40078</span></span>\n            = <span class=\"frac\"><span class=\"num\">1.51867</span><span class=\"den\">0.40078</span></span>\n            &approx; <b>3.7893</b>\n        </p>\n    </div>\n    <p>Evaluate <i>f(x<sub>3</sub>)</i>: <i>f(3.7893) = 2(3.7893) &minus; log<sub>10</sub>(3.7893) &minus; 7 = 7.57860 &minus; 0.57856 &minus; 7 = +0.00004 &approx; 0</i>.</p>\n    <div><span class=\"highlight-ans\">Final Converged Root: x &approx; 3.7893</span></div>\n</div>\n\n<hr>\n\n<!-- Q7 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q7. Find the missing terms in the following table using finite differences: <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <table class=\"iter-table\">\n        <tr><th>x</th><td>0</td><td>5</td><td>10</td><td>15</td><td>20</td><td>25</td><td>30</td></tr>\n        <tr><th>y</th><td>1</td><td>3</td><td><b>? (y<sub>2</sub>)</b></td><td>73</td><td>225</td><td><b>? (y<sub>5</sub>)</b></td><td>1153</td></tr>\n    </table>\n    <p><strong>Solution:</strong></p>\n    <p>Let the missing values be <i>y<sub>2</sub></i> (at <i>x = 10</i>) and <i>y<sub>5</sub></i> (at <i>x = 25</i>).</p>\n    <p>Since 5 values are given (<i>y<sub>0</sub>, y<sub>1</sub>, y<sub>3</sub>, y<sub>4</sub>, y<sub>6</sub></i>), the data can be represented by a polynomial of degree 4.</p>\n    <p>Therefore, the 5th finite difference is identically zero: <b>&Delta;<sup>5</sup> y<sub>0</sub> = 0</b> and <b>&Delta;<sup>5</sup> y<sub>1</sub> = 0</b>.</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            Using shift operator <i>&Delta; = E &minus; 1</i>:<br>\n            (E &minus; 1)<sup>5</sup> y = (E<sup>5</sup> &minus; 5E<sup>4</sup> + 10E<sup>3</sup> &minus; 10E<sup>2</sup> + 5E &minus; 1) y = 0\n        </p>\n    </div>\n    <p class=\"step-label\">Equation 1 (applying on y<sub>0</sub>):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            y<sub>5</sub> &minus; 5y<sub>4</sub> + 10y<sub>3</sub> &minus; 10y<sub>2</sub> + 5y<sub>1</sub> &minus; y<sub>0</sub> = 0<br>\n            y<sub>5</sub> &minus; 5(225) + 10(73) &minus; 10y<sub>2</sub> + 5(3) &minus; 1 = 0<br>\n            y<sub>5</sub> &minus; 1125 + 730 &minus; 10y<sub>2</sub> + 15 &minus; 1 = 0<br>\n            <b>&minus;10y<sub>2</sub> + y<sub>5</sub> = 381</b> &emsp;&emsp;— (Equation 1)\n        </p>\n    </div>\n    <p class=\"step-label\">Equation 2 (applying on y<sub>1</sub>):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            y<sub>6</sub> &minus; 5y<sub>5</sub> + 10y<sub>4</sub> &minus; 10y<sub>3</sub> + 5y<sub>2</sub> &minus; y<sub>1</sub> = 0<br>\n            1153 &minus; 5y<sub>5</sub> + 10(225) &minus; 10(73) + 5y<sub>2</sub> &minus; 3 = 0<br>\n            1153 &minus; 5y<sub>5</sub> + 2250 &minus; 730 + 5y<sub>2</sub> &minus; 3 = 0<br>\n            5y<sub>2</sub> &minus; 5y<sub>5</sub> + 2670 = 0 &rArr; y<sub>2</sub> &minus; y<sub>5</sub> = &minus;534 &rArr; <b>y<sub>5</sub> &minus; y<sub>2</sub> = 534</b> &emsp;&emsp;— (Equation 2)\n        </p>\n    </div>\n    <p class=\"step-label\">Solving the Linear System:</p>\n    <p>From Equation 2: <i>y<sub>5</sub> = y<sub>2</sub> + 534</i>.</p>\n    <p>Substitute into Equation 1: <i>&minus;10y<sub>2</sub> + (y<sub>2</sub> + 534) = 381 &rArr; &minus;9y<sub>2</sub> = 381 &minus; 534 = &minus;153 &rArr; <b>y<sub>2</sub> = 17</b></i>.</p>\n    <p>Then <i>y<sub>5</sub> = 17 + 534 = <b>551</b></i>.</p>\n    <div><span class=\"highlight-ans\">Missing Values: y<sub>2</sub> = 17 (at x = 10) &emsp;|&emsp; y<sub>5</sub> = 551 (at x = 25)</span></div>\n</div>\n\n<hr>\n\n<!-- Q8 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q8. Evaluate <i>I = &int;<sub>3</sub><sup>7</sup> x<sup>2</sup> log<sub>10</sub>(x) dx</i> using Simpson's 1/3 rule with <i>n = 4</i>. <span class=\"q-marks\">[7.5 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Given limits <i>a = 3, b = 7</i>, and number of sub-intervals <i>n = 4</i>.</p>\n    <p>Step size: <i>h = (b &minus; a) / n = (7 &minus; 3) / 4 = <b>1</b></i>.</p>\n    <table class=\"iter-table\">\n        <tr><th>i</th><th>x<sub>i</sub></th><th>Function f(x) = x<sup>2</sup> log<sub>10</sub>(x)</th><th>Ordinate y<sub>i</sub></th></tr>\n        <tr><td>0</td><td>3</td><td>3<sup>2</sup> &bull; log<sub>10</sub>(3) = 9 &times; 0.477121</td><td><b>4.2941</b></td></tr>\n        <tr><td>1</td><td>4</td><td>4<sup>2</sup> &bull; log<sub>10</sub>(4) = 16 &times; 0.602060</td><td><b>9.6330</b></td></tr>\n        <tr><td>2</td><td>5</td><td>5<sup>2</sup> &bull; log<sub>10</sub>(5) = 25 &times; 0.698970</td><td><b>17.4743</b></td></tr>\n        <tr><td>3</td><td>6</td><td>6<sup>2</sup> &bull; log<sub>10</sub>(6) = 36 &times; 0.778151</td><td><b>28.0134</b></td></tr>\n        <tr><td>4</td><td>7</td><td>7<sup>2</sup> &bull; log<sub>10</sub>(7) = 49 &times; 0.845098</td><td><b>41.4099</b></td></tr>\n    </table>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Simpson's 1/3 Rule Formula:</b><br>\n            I = <span class=\"frac\"><span class=\"num\">h</span><span class=\"den\">3</span></span> [ (y<sub>0</sub> + y<sub>4</sub>) + 4(y<sub>1</sub> + y<sub>3</sub>) + 2(y<sub>2</sub>) ]\n        </p>\n        <p class=\"formula\">\n            Sum of Extremes:&emsp; y<sub>0</sub> + y<sub>4</sub> = 4.2941 + 41.4099 = <b>45.7040</b><br>\n            Sum of Odd Ordinates:&emsp; 4(y<sub>1</sub> + y<sub>3</sub>) = 4(9.6330 + 28.0134) = 4(37.6464) = <b>150.5856</b><br>\n            Sum of Even Ordinates:&emsp; 2(y<sub>2</sub>) = 2(17.4743) = <b>34.9486</b>\n        </p>\n        <p class=\"formula\">\n            Total Bracket Sum = 45.7040 + 150.5856 + 34.9486 = <b>231.2382</b><br>\n            I = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> &times; 231.2382 = <b>77.0794</b>\n        </p>\n    </div>\n    <div><span class=\"highlight-ans\">Evaluated Integral: I &approx; 77.0794</span></div>\n</div>\n\n<!-- ==================== SECTION C ==================== -->\n<div class=\"sec-title\">Section – C (Long Answer Questions &bull; 15 Marks Each &bull; Attempt Any Three)</div>\n\n<!-- Q9 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q9. Use Newton-Raphson method to find a real root of <i>sin(x) = x / 2</i> correct to 3 decimal places between &pi;/2 and &pi;. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Let <i>f(x) = sin(x) &minus; <span class=\"frac\"><span class=\"num\">x</span><span class=\"den\">2</span></span> = 0</i>.</p>\n    <p>Differentiating with respect to x: <i>f'(x) = cos(x) &minus; 0.5</i>.</p>\n    <p>Given interval: [&pi;/2, &pi;] &approx; [1.5708, 3.1416] radians.</p>\n    <p>Let initial approximation be <b>x<sub>0</sub> = 2.0 radians</b>.</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Newton-Raphson Iteration Formula:</b><br>\n            x<sub>n+1</sub> = x<sub>n</sub> &minus; <span class=\"frac\"><span class=\"num\">f(x<sub>n</sub>)</span><span class=\"den\">f'(x<sub>n</sub>)</span></span>\n        </p>\n    </div>\n    <p class=\"step-label\">Iteration 1 (at x<sub>0</sub> = 2.0):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            f(2.0) = sin(2.0) &minus; 1.0 = 0.90930 &minus; 1.0 = <b>&minus;0.09070</b><br>\n            f'(2.0) = cos(2.0) &minus; 0.5 = &minus;0.41615 &minus; 0.5 = <b>&minus;0.91615</b><br>\n            x<sub>1</sub> = 2.0 &minus; <span class=\"frac\"><span class=\"num\">&minus;0.09070</span><span class=\"den\">&minus;0.91615</span></span> = 2.0 &minus; 0.09900 = <b>1.90100</b>\n        </p>\n    </div>\n    <p class=\"step-label\">Iteration 2 (at x<sub>1</sub> = 1.90100):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            f(1.90100) = sin(1.90100) &minus; <span class=\"frac\"><span class=\"num\">1.90100</span><span class=\"den\">2</span></span> = 0.94598 &minus; 0.95050 = <b>&minus;0.00452</b><br>\n            f'(1.90100) = cos(1.90100) &minus; 0.5 = &minus;0.32422 &minus; 0.5 = <b>&minus;0.82422</b><br>\n            x<sub>2</sub> = 1.90100 &minus; <span class=\"frac\"><span class=\"num\">&minus;0.00452</span><span class=\"den\">&minus;0.82422</span></span> = 1.90100 &minus; 0.00548 = <b>1.89552</b>\n        </p>\n    </div>\n    <p class=\"step-label\">Iteration 3 (at x<sub>2</sub> = 1.89552):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            f(1.89552) = sin(1.89552) &minus; <span class=\"frac\"><span class=\"num\">1.89552</span><span class=\"den\">2</span></span> = 0.94775 &minus; 0.94776 = <b>&minus;0.00001</b><br>\n            f'(1.89552) = cos(1.89552) &minus; 0.5 = &minus;0.31899 &minus; 0.5 = <b>&minus;0.81899</b><br>\n            x<sub>3</sub> = 1.89552 &minus; <span class=\"frac\"><span class=\"num\">&minus;0.00001</span><span class=\"den\">&minus;0.81899</span></span> = 1.89552 &minus; 0.00001 = <b>1.89549</b>\n        </p>\n    </div>\n    <div><span class=\"highlight-ans\">Root: x &approx; 1.895 radians (or &approx; 108.57&deg;)</span></div>\n</div>\n\n<hr>\n\n<!-- Q10 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q10. Find the Lagrange interpolating polynomial of degree 2 for <i>y = log<sub>e</sub>(x)</i> from the given table. Hence determine <i>log<sub>e</sub>(2.7)</i>. <span class=\"q-marks\">[15 Marks]</span></div>\n    <table class=\"iter-table\">\n        <tr><th>x</th><td>2.0</td><td>2.5</td><td>3.0</td></tr>\n        <tr><th>y = log<sub>e</sub>(x)</th><td>0.69315</td><td>0.91629</td><td>1.09861</td></tr>\n    </table>\n    <p><strong>Solution:</strong></p>\n    <p>Given <i>x<sub>0</sub> = 2.0, y<sub>0</sub> = 0.69315</i>; &nbsp; <i>x<sub>1</sub> = 2.5, y<sub>1</sub> = 0.91629</i>; &nbsp; <i>x<sub>2</sub> = 3.0, y<sub>2</sub> = 1.09861</i>.</p>\n    <p>Target value: <i>x = 2.7</i>.</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Lagrange Interpolation Formula for n = 2:</b><br>\n            P<sub>2</sub>(x) = L<sub>0</sub>(x) y<sub>0</sub> + L<sub>1</sub>(x) y<sub>1</sub> + L<sub>2</sub>(x) y<sub>2</sub>\n        </p>\n    </div>\n    <p class=\"step-label\">Calculating Lagrange Cardinal Polynomials at x = 2.7:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            L<sub>0</sub>(2.7) = <span class=\"frac\"><span class=\"num\">(2.7 &minus; 2.5)(2.7 &minus; 3.0)</span><span class=\"den\">(2.0 &minus; 2.5)(2.0 &minus; 3.0)</span></span>\n            = <span class=\"frac\"><span class=\"num\">(0.2)(&minus;0.3)</span><span class=\"den\">(&minus;0.5)(&minus;1.0)</span></span>\n            = <span class=\"frac\"><span class=\"num\">&minus;0.06</span><span class=\"den\">0.50</span></span>\n            = <b>&minus;0.12</b>\n        </p>\n        <p class=\"formula\">\n            L<sub>1</sub>(2.7) = <span class=\"frac\"><span class=\"num\">(2.7 &minus; 2.0)(2.7 &minus; 3.0)</span><span class=\"den\">(2.5 &minus; 2.0)(2.5 &minus; 3.0)</span></span>\n            = <span class=\"frac\"><span class=\"num\">(0.7)(&minus;0.3)</span><span class=\"den\">(0.5)(&minus;0.5)</span></span>\n            = <span class=\"frac\"><span class=\"num\">&minus;0.21</span><span class=\"den\">&minus;0.25</span></span>\n            = <b>+0.84</b>\n        </p>\n        <p class=\"formula\">\n            L<sub>2</sub>(2.7) = <span class=\"frac\"><span class=\"num\">(2.7 &minus; 2.0)(2.7 &minus; 2.5)</span><span class=\"den\">(3.0 &minus; 2.0)(3.0 &minus; 2.5)</span></span>\n            = <span class=\"frac\"><span class=\"num\">(0.7)(0.2)</span><span class=\"den\">(1.0)(0.5)</span></span>\n            = <span class=\"frac\"><span class=\"num\">0.14</span><span class=\"den\">0.50</span></span>\n            = <b>+0.28</b>\n        </p>\n        <p class=\"formula\">\n            <i>Verification: L<sub>0</sub> + L<sub>1</sub> + L<sub>2</sub> = &minus;0.12 + 0.84 + 0.28 = 1.00 &check;</i>\n        </p>\n    </div>\n    <p class=\"step-label\">Evaluating P<sub>2</sub>(2.7):</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            P<sub>2</sub>(2.7) = (&minus;0.12)(0.69315) + (0.84)(0.91629) + (0.28)(1.09861)<br>\n            = &minus;0.083178 + 0.769684 + 0.307611<br>\n            = <b>0.994117 &approx; 0.99412</b>\n        </p>\n    </div>\n    <p><i>(Exact analytical value: ln(2.7) &approx; 0.99325; error &approx; 0.00087.)</i></p>\n    <div><span class=\"highlight-ans\">Interpolated Value: log<sub>e</sub>(2.7) &approx; 0.99412</span></div>\n</div>\n\n<hr>\n\n<!-- Q11 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q11. Use Simpson's 3/8 rule to evaluate <i>&int;<sub>0</sub><sup>1</sup> <span class=\"frac\"><span class=\"num\">dx</span><span class=\"den\">1 + x</span></span></i> with <i>h = 1/6</i>. <span class=\"q-marks\">[15 Marks]</span></div>\n    <p><strong>Solution:</strong></p>\n    <p>Given <i>a = 0, b = 1</i>, step size <i>h = 1/6 &rArr; n = (1 &minus; 0)/(1/6) = 6</i> subintervals.</p>\n    <p>Integrand: <i>f(x) = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">1 + x</span></span></i>.</p>\n    <table class=\"iter-table\">\n        <tr><th>i</th><th>x<sub>i</sub></th><th>Exact y<sub>i</sub> = 1 / (1 + x<sub>i</sub>)</th><th>Decimal Value</th></tr>\n        <tr><td>0</td><td>0</td><td>1 / 1</td><td><b>1.000000</b></td></tr>\n        <tr><td>1</td><td>1/6</td><td>1 / (7/6) = 6/7</td><td><b>0.857143</b></td></tr>\n        <tr><td>2</td><td>2/6</td><td>1 / (8/6) = 6/8 = 3/4</td><td><b>0.750000</b></td></tr>\n        <tr><td>3</td><td>3/6</td><td>1 / (9/6) = 6/9 = 2/3</td><td><b>0.666667</b></td></tr>\n        <tr><td>4</td><td>4/6</td><td>1 / (10/6) = 6/10 = 3/5</td><td><b>0.600000</b></td></tr>\n        <tr><td>5</td><td>5/6</td><td>1 / (11/6) = 6/11</td><td><b>0.545455</b></td></tr>\n        <tr><td>6</td><td>1</td><td>1 / 2</td><td><b>0.500000</b></td></tr>\n    </table>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <b>Simpson's 3/8 Rule Formula:</b><br>\n            I = <span class=\"frac\"><span class=\"num\">3h</span><span class=\"den\">8</span></span> [ (y<sub>0</sub> + y<sub>6</sub>) + 3(y<sub>1</sub> + y<sub>2</sub> + y<sub>4</sub> + y<sub>5</sub>) + 2(y<sub>3</sub>) ]\n        </p>\n        <p class=\"formula\">\n            Extremes:&emsp; y<sub>0</sub> + y<sub>6</sub> = 1.000000 + 0.500000 = <b>1.500000</b><br>\n            Non-multiples of 3:&emsp; 3(y<sub>1</sub> + y<sub>2</sub> + y<sub>4</sub> + y<sub>5</sub>) = 3(0.857143 + 0.750000 + 0.600000 + 0.545455) = 3(2.752598) = <b>8.257794</b><br>\n            Multiples of 3:&emsp; 2(y<sub>3</sub>) = 2(0.666667) = <b>1.333334</b>\n        </p>\n        <p class=\"formula\">\n            Sum of brackets = 1.500000 + 8.257794 + 1.333334 = <b>11.091128</b><br>\n            I = <span class=\"frac\"><span class=\"num\">3(1/6)</span><span class=\"den\">8</span></span> &times; 11.091128 = <span class=\"frac\"><span class=\"num\">1/2</span><span class=\"den\">8</span></span> &times; 11.091128 = <span class=\"frac\"><span class=\"num\">11.091128</span><span class=\"den\">16</span></span> = <b>0.693196</b>\n        </p>\n    </div>\n    <p><i>(Exact analytical integral: &int;<sub>0</sub><sup>1</sup> dx/(1+x) = [ln(1+x)]<sub>0</sub><sup>1</sup> = ln(2) &approx; 0.693147. Highly accurate to 4 decimal places.)</i></p>\n    <div><span class=\"highlight-ans\">Evaluated Integral: I &approx; 0.693196</span></div>\n</div>\n\n<hr>\n\n<!-- Q12 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q12. Solve the following linear system using Gauss-Seidel iterative method: <span class=\"q-marks\">[15 Marks]</span></div>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            6x + y + z = 20<br>\n            x + 4y &minus; z = 6<br>\n            x &minus; y + 5z = 7\n        </p>\n    </div>\n    <p><strong>Solution:</strong></p>\n    <p class=\"step-label\">Step 1: Check Diagonal Dominance Condition:</p>\n    <ul>\n        <li>Equation 1: |6| &gt; |1| + |1| = 2 &emsp;(Dominant in x &check;)</li>\n        <li>Equation 2: |4| &gt; |1| + |&minus;1| = 2 &emsp;(Dominant in y &check;)</li>\n        <li>Equation 3: |5| &gt; |1| + |&minus;1| = 2 &emsp;(Dominant in z &check;)</li>\n    </ul>\n    <p>The system is strictly diagonally dominant. Convergence is guaranteed.</p>\n    <p class=\"step-label\">Step 2: Express in Iterative Form:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            x<sup>(k+1)</sup> = <span class=\"frac\"><span class=\"num\">20 &minus; y<sup>(k)</sup> &minus; z<sup>(k)</sup></span><span class=\"den\">6</span></span><br>\n            y<sup>(k+1)</sup> = <span class=\"frac\"><span class=\"num\">6 &minus; x<sup>(k+1)</sup> + z<sup>(k)</sup></span><span class=\"den\">4</span></span><br>\n            z<sup>(k+1)</sup> = <span class=\"frac\"><span class=\"num\">7 &minus; x<sup>(k+1)</sup> + y<sup>(k+1)</sup></span><span class=\"den\">5</span></span>\n        </p>\n    </div>\n    <p class=\"step-label\">Step 3: Iteration Table (Initial Approximation: x<sup>(0)</sup> = 0, y<sup>(0)</sup> = 0, z<sup>(0)</sup> = 0):</p>\n    <table class=\"iter-table\">\n        <tr><th>Iteration (k)</th><th>x = (20 &minus; y &minus; z) / 6</th><th>y = (6 &minus; x + z) / 4</th><th>z = (7 &minus; x + y) / 5</th></tr>\n        <tr><td>1</td><td>(20 &minus; 0 &minus; 0)/6 = <b>3.3333</b></td><td>(6 &minus; 3.3333 + 0)/4 = <b>0.6667</b></td><td>(7 &minus; 3.3333 + 0.6667)/5 = <b>0.8667</b></td></tr>\n        <tr><td>2</td><td>(20 &minus; 0.6667 &minus; 0.8667)/6 = <b>3.0778</b></td><td>(6 &minus; 3.0778 + 0.8667)/4 = <b>0.9472</b></td><td>(7 &minus; 3.0778 + 0.9472)/5 = <b>0.9739</b></td></tr>\n        <tr><td>3</td><td>(20 &minus; 0.9472 &minus; 0.9739)/6 = <b>3.0131</b></td><td>(6 &minus; 3.0131 + 0.9739)/4 = <b>0.9902</b></td><td>(7 &minus; 3.0131 + 0.9902)/5 = <b>0.9954</b></td></tr>\n        <tr><td>4</td><td>(20 &minus; 0.9902 &minus; 0.9954)/6 = <b>3.0024</b></td><td>(6 &minus; 3.0024 + 0.9954)/4 = <b>0.9983</b></td><td>(7 &minus; 3.0024 + 0.9983)/5 = <b>0.9992</b></td></tr>\n        <tr><td>5</td><td>(20 &minus; 0.9983 &minus; 0.9992)/6 = <b>3.0004</b></td><td>(6 &minus; 3.0004 + 0.9992)/4 = <b>0.9997</b></td><td>(7 &minus; 3.0004 + 0.9997)/5 = <b>0.9999</b></td></tr>\n        <tr><td>6</td><td><b>3.0000</b></td><td><b>1.0000</b></td><td><b>1.0000</b></td></tr>\n    </table>\n    <div><span class=\"highlight-ans\">Converged Solution: x = 3, &nbsp; y = 1, &nbsp; z = 1</span></div>\n</div>\n\n<hr>\n\n<!-- Q13 -->\n<div class=\"q-box\">\n    <div class=\"q-title\">Q13. Using Fourth-Order Runge-Kutta method, find <i>y(0.1)</i> and <i>y(0.2)</i> correct to 4 decimal places, given: <span class=\"q-marks\">[15 Marks]</span></div>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            <span class=\"frac\"><span class=\"num\">dy</span><span class=\"den\">dx</span></span> = y &minus; x, &emsp;with initial condition y(0) = 2\n        </p>\n    </div>\n    <p><strong>Solution:</strong></p>\n    <p>Given <i>f(x, y) = y &minus; x</i>, initial point <i>x<sub>0</sub> = 0, y<sub>0</sub> = 2</i>, step size <i>h = 0.1</i>.</p>\n    <p class=\"step-label\">Part 1: Calculation of y(0.1) from x<sub>0</sub> = 0, y<sub>0</sub> = 2:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            k<sub>1</sub> = h &bull; f(x<sub>0</sub>, y<sub>0</sub>) = 0.1(2 &minus; 0) = <b>0.200000</b><br>\n            k<sub>2</sub> = h &bull; f(x<sub>0</sub> + <span class=\"frac\"><span class=\"num\">h</span><span class=\"den\">2</span></span>, y<sub>0</sub> + <span class=\"frac\"><span class=\"num\">k<sub>1</sub></span><span class=\"den\">2</span></span>) = 0.1 &bull; f(0.05, 2.10) = 0.1(2.10 &minus; 0.05) = <b>0.205000</b><br>\n            k<sub>3</sub> = h &bull; f(x<sub>0</sub> + <span class=\"frac\"><span class=\"num\">h</span><span class=\"den\">2</span></span>, y<sub>0</sub> + <span class=\"frac\"><span class=\"num\">k<sub>2</sub></span><span class=\"den\">2</span></span>) = 0.1 &bull; f(0.05, 2.1025) = 0.1(2.1025 &minus; 0.05) = <b>0.205250</b><br>\n            k<sub>4</sub> = h &bull; f(x<sub>0</sub> + h, y<sub>0</sub> + k<sub>3</sub>) = 0.1 &bull; f(0.1, 2.20525) = 0.1(2.20525 &minus; 0.1) = <b>0.210525</b>\n        </p>\n        <p class=\"formula\">\n            k = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> (k<sub>1</sub> + 2k<sub>2</sub> + 2k<sub>3</sub> + k<sub>4</sub>)<br>\n            = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> (0.200000 + 0.410000 + 0.410500 + 0.210525) = <span class=\"frac\"><span class=\"num\">1.231025</span><span class=\"den\">6</span></span> &approx; <b>0.205171</b>\n        </p>\n        <p class=\"formula\">\n            <b>y(0.1) = y<sub>0</sub> + k = 2 + 0.205171 = 2.2052</b>\n        </p>\n    </div>\n    \n    <p class=\"step-label\">Part 2: Calculation of y(0.2) from x<sub>1</sub> = 0.1, y<sub>1</sub> = 2.205171:</p>\n    <div class=\"math-box\">\n        <p class=\"formula\">\n            k<sub>1</sub> = h &bull; f(x<sub>1</sub>, y<sub>1</sub>) = 0.1(2.205171 &minus; 0.1) = <b>0.210517</b><br>\n            k<sub>2</sub> = h &bull; f(0.1 + 0.05, 2.205171 + 0.105258) = 0.1 &bull; f(0.15, 2.310430) = 0.1(2.310430 &minus; 0.15) = <b>0.216043</b><br>\n            k<sub>3</sub> = h &bull; f(0.1 + 0.05, 2.205171 + 0.108022) = 0.1 &bull; f(0.15, 2.313193) = 0.1(2.313193 &minus; 0.15) = <b>0.216319</b><br>\n            k<sub>4</sub> = h &bull; f(0.1 + 0.1, 2.205171 + 0.216319) = 0.1 &bull; f(0.2, 2.421490) = 0.1(2.421490 &minus; 0.2) = <b>0.222149</b>\n        </p>\n        <p class=\"formula\">\n            k = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> (k<sub>1</sub> + 2k<sub>2</sub> + 2k<sub>3</sub> + k<sub>4</sub>)<br>\n            = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> (0.210517 + 0.432086 + 0.432638 + 0.222149) = <span class=\"frac\"><span class=\"num\">1.297390</span><span class=\"den\">6</span></span> &approx; <b>0.216232</b>\n        </p>\n        <p class=\"formula\">\n            <b>y(0.2) = y<sub>1</sub> + k = 2.205171 + 0.216232 = 2.4214</b>\n        </p>\n    </div>\n    <div><span class=\"highlight-ans\">y(0.1) = 2.2052 &emsp;|&emsp; y(0.2) = 2.4214</span></div>\n</div>"}};
